def hydrate_time(nanoseconds, tz=None):
    """Hydrator for `Time` and `LocalTime` values.

    Parameters
    ----------
    nanoseconds : int
        Number of nanoseconds since the Unix epoch (January 1 1970).
    tz : str or datetime.tzinfo, optional
        Time zone for the resulting time. If a string is supplied it
        must be a valid IANA time zone name. If ``None`` the time will
        be returned as a naive ``datetime.time`` object representing
        UTC.

    Returns
    -------
    datetime.time
        The time corresponding to the given nanoseconds value.
    """
    import datetime
    try:
        ns = int(nanoseconds)
    except Exception:
        raise ValueError("nanoseconds must be an integer") from None

    # Resolve the timezone
    if tz is None:
        tzinfo = None
    else:
        if isinstance(tz, str):
            try:
                from zoneinfo import ZoneInfo
            except ImportError:
                raise ImportError(
                    "zoneinfo module required for string tz arguments"
                ) from None
            try:
                tzinfo = ZoneInfo(tz)
            except Exception as exc:
                raise ValueError(f"Invalid time zone name: {tz!r}") from exc
        elif isinstance(tz, datetime.tzinfo):
            tzinfo = tz
        else:
            raise TypeError("tz must be None, a str iana name, or a tzinfo instance")

    # Convert nanoseconds to seconds and remaining nanoseconds
    seconds = ns // 1_000_000_000
    ns_remainder = ns % 1_000_000_000

    # Build a datetime object
    try:
        if tzinfo is None:
            dt = datetime.datetime.utcfromtimestamp(seconds)
        else:
            dt = datetime.datetime.fromtimestamp(seconds, tz=tzinfo)
    except Exception as exc:
        raise ValueError(f"Invalid nanoseconds value: {ns}") from exc

    # Apply remaining nanoseconds (converted to microseconds)
    microsecond = ns_remainder // 1000
    try:
        dt = dt.replace(microsecond=microsecond)
    except Exception as exc:
        raise ValueError("Failed to set microseconds") from exc

    return dt.time()
