    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Collect all user-visible attributes: exclude private attributes
    # and callables to avoid methods/other objects.
    all_attrs = {
        name: value
        for name, value in vars(self).items()
        if not name.startswith("_") and not callable(value)
    }

    # If no keys requested, return all attributes.
    if not keys:
        return dict(all_attrs)

    # Prepare list of (name, value) pairs for indexed access.
    ordered_attrs = list(all_attrs.items())

    result = {}
    for key in keys:
        if isinstance(key, int):
            # Index-based lookup
            if key < 0 or key >= len(ordered_attrs):
                raise IndexError(f"Index {key} out of bounds for record with {len(ordered_attrs)} items")
            name, value = ordered_attrs[key]
            result[name] = value
        else:
            # Key-based lookup (string or other hashable)
            value = all_attrs.get(key, None)
            result[key] = value
    return result<|return|>

def data(self, *keys):
        """Return the keys and values of this record as a dictionary,
        optionally including only certain values by index or key. Keys
        provided in the items that are not in the record will be
        inserted with a value of :const:`None`; indexes provided
        that are out of bounds will trigger an :exc:`IndexError`.

        :param keys: indexes or keys of the items to include; if none
                      are provided, all values will be included
        :return: dictionary of values, keyed by field name
        :raises: :exc:`IndexError` if an out-of-bounds index is specified
        """
        # Determine the data and field names.  These names are conventional
        # in the library that this code is part of, but if they are not
        # present we try alternative attribute names so that the method
        # remains robust.
        try:
            fields = self._fields
            values = self._data
        except AttributeError:
            # Fallback: try common alternatives
            if hasattr(self, 'keys'):
                fields = self.keys
            else:
                fields = getattr(self, 'headers', [])
            if hasattr(self, 'values'):
                values = self.values
            else:
                values = getattr(self, 'data', [])
        # If no keys were supplied, return all values
        if not keys:
            return dict(zip(fields, values))
        result = {}
        for key in keys:
            if isinstance(key, int):
                # Treat as an index
                if key < 0 or key >= len(values):
                    raise IndexError(f'Index {key} out of range')
                result[fields[key]] = values[key]
            else:
                # Treat as a literal key
                if key in fields:
                    idx = fields.index(key)
                    result[key] = values[idx]
                else:
                    result[key] = None
        return result<|return|>

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
        """Appends a DISCARD message to the output queue.

        :param n: number of records to discard, default = -1 (ALL)
        :param qid: query ID to discard for, default = -1 (last query)
        :param dehydration_hooks:
            Hooks to dehydrate types (dict from type (class) to dehydration
            function). Dehydration functions receive the value and returns an
            object of type understood by packstream.
        :param hydration_hooks:
            Hooks to hydrate types (mapping from type (class) to
            dehydration function). Dehydration functions receive the value of
            type understood by packstream and are free to return anything.
        :param handlers: handler functions passed into the returned Response object
        """
        # Validate input types
        if not isinstance(n, int):
            raise TypeError(f"'n' must be an int, got {type(n).__name__}")
        if not isinstance(qid, int):
            raise TypeError(f"'qid' must be an int, got {type(qid).__name__}")

        # Construct the message payload
        message = {
            "type": "DISCARD",
            "n": n,
            "qid": qid,
        }

        # Attach hooks to the message if provided
        if dehydration_hooks is not None:
            if not isinstance(dehydration_hooks, dict):
                raise TypeError(
                    f"'dehydration_hooks' must be a dict, got {type(dehydration_hooks).__name__}"
                )
            message["dehydration_hooks"] = dehydration_hooks
        if hydration_hooks is not None:
            if not isinstance(hydration_hooks, dict):
                raise TypeError(
                    f"'hydration_hooks' must be a dict, got {type(hydration_hooks).__name__}"
                )
            message["hydration_hooks"] = hydration_hooks

        # Append the message to the instance's output queue
        if not hasattr(self, "_out_queue"):
            # Lazily create the queue if it does not exist
            self._out_queue = []
        self._out_queue.append(message)

        # Prepare a simple Response object if a custom one is not defined
        ResponseCls = getattr(self, "Response", None)

        if ResponseCls is None:
            # Define a minimal Response class
            class _Response:
                def __init__(self, msg, dehydration_hooks=None,
                             hydration_hooks=None, **handlers):
                    self.message = msg
                    self.dehydration_hooks = dehydration_hooks or {}
                    self.hydration_hooks = hydration_hooks or {}
                    self.handlers = handlers

                def __repr__(self):
                    return f"<Response msg={self.message!r}>"

            ResponseCls = _Response

        # Instantiate and return the Response
        return ResponseCls(
            msg=message,
            dehydration_hooks=dehydration_hooks,
            hydration_hooks=hydration_hooks,
            **handlers,
        )<|return|>

