def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Validate input types
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if not name.isidentifier():
        raise ValueError(f"Invalid identifier for class name: {name!r}")
    if not isinstance(fields, dict):
        raise TypeError("fields must be a dict")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dict")

    # Build class attributes
    attrs = {}

    # Add the provided fields as attributes with default values
    for field_name, default_value in fields.items():
        if not isinstance(field_name, str):
            raise TypeError("field names must be strings")
        attrs[field_name] = default_value

    # Store the SRID map on the class for later reference
    attrs['_srid_map'] = srid_map

    # Provide a simple __init__ that accepts keyword arguments for the fields
    def __init__(self, **kwargs):
        for key in attrs:
            if key in ('_srid_map', '__doc__', '__module__', '__qualname__'):
                continue
            setattr(self, key, kwargs.get(key, attrs[key]))
    attrs['__init__'] = __init__

    # Define a helpful __repr__
    def __repr__(self):
        field_strings = ", ".join(f"{k}={getattr(self, k)!r}" for k in fields)
        return f"{name}({field_strings})"
    attrs['__repr__'] = __repr__

    # Attach a descriptive docstring to the class
    attrs['__doc__'] = f"Dynamically-generated subclass of Point named {name}"

    # Import or assume existence of a base Point class
    try:
        Base = Point
    except NameError as exc:
        raise NameError("A global 'Point' class must be defined before calling point_type") from exc

