    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    if not callable(key):
        raise TypeError("key must be a callable that returns a hashable key")

    def decorator(func):
        """Wrap the function with caching logic."""
        def wrapper(*args, **kwargs):
            try:
                cache_key = key(*args, **kwargs)
            except Exception as exc:
                raise ValueError("Key function raised an exception: %s" % exc) from exc

            # If the key is not hashable, cache lookup will fail
            try:
                key_hashable = cache_key
                _ = hash(key_hashable)
            except TypeError as exc:
                raise ValueError("Cache key is not hashable: %s" % key_hashable) from exc

            def _lookup_and_update():
                if key_hashable in cache:
                    return cache[key_hashable]
                result = func(*args, **kwargs)
                cache[key_hashable] = result
                return result

            if lock is None:
                return _lookup_and_update()
            else:
                # Support both locks that are context managers and those that
                # provide acquire/release methods.
                if hasattr(lock, "__enter__") and hasattr(lock, "__exit__"):
                    with lock:
                        return _lookup_and_update()
                else:
                    lock.acquire()
                    try:
                        return _lookup_and_update()
                    finally:
                        lock.release()
        return wrapper
    return decorator<|return|>

