@classmethod
def _reset_logging(cls):
    """Reset logging for this class."""
    import logging
    try:
        logger_name = f"{cls.__module__}.{cls.__qualname__}"
        logger = logging.getLogger(logger_name)
        # Remove all existing handlers
        handlers = logger.handlers[:]
        for handler in handlers:
            logger.removeHandler(handler)
            handler.flush()
            handler.close()
        # Reset logger level to default
        logger.setLevel(logging.WARNING)
        # Prevent "no handler found" warnings by adding a NullHandler
        if not logger.handlers:
            logger.addHandler(logging.NullHandler())
    except Exception as exc:
        raise RuntimeError(f"Failed to reset logging for {logger_name}") from exc<|return|>

@classmethod
def _reset_logging(cls):
    """Reset the logging configuration to default settings."""
    import logging
    try:
        root = logging.getLogger()
        # Remove all existing handlers
        for handler in root.handlers[:]:
            root.removeHandler(handler)
        root.handlers = []
        # Set a default logging level and basic configuration
        root.setLevel(logging.WARNING)
        logging.basicConfig(
            level=logging.WARNING,
            format="%(levelname)s:%(name)s:%(message)s",
        )
    except Exception:
        # Silently ignore failures; callers can handle if needed
        pass<|return|>

