def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Preserve order while removing duplicates
    unique = []
    seen = set()
    for cls in classes:
        if cls not in seen:
            seen.add(cls)
            unique.append(cls)

    # Build the minimal list: drop any class that is a superclass of another
    minimal = []
    for cls in unique:
        # Skip if any other class is a subclass of this one
        redundant = False
        for other in unique:
            if other is cls:
                continue
            try:
                if issubclass(other, cls):
                    redundant = True
                    break
            except TypeError:
                # Skip non‑class objects
                continue
        if not redundant:
            minimal.append(cls)

    return minimal<|return|>

