        to_remove = []
        for i, r in enumerate(result):
            if r is c:
                skip = True
                break
            if issubclass(c, r):
                # a more specific class already present
                skip = True
                break
            if issubclass(r, c):
                # a more general class already present
                to_remove.append(i)
        if skip:
