    # Normalise to a list; if empty return empty list
    try:
        base_list = list(classes)
    except TypeError:
        return []

    redundant = set()
    # Identify superclasses that have a more derived class in the list
    for i, cls_i in enumerate(base_list):
        if not isinstance(cls_i, type):
            continue
        for j, cls_j in enumerate(base_list):
            if i == j or not isinstance(cls_j, type):
                continue
            try:
                # If cls_j is subclass of cls_i (and not the same), cls_i is redundant
                if issubclass(cls_j, cls_i) and cls_j is not cls_i:
                    redundant.add(cls_i)
                    break
            except Exception:
                # issubclass can raise TypeError if inputs are not proper classes
                continue

    # Build the minimal ordered list, discarding duplicates
    result = []
    seen = set()
    for cls in base_list:
        if not isinstance(cls, type):
            continue
        if cls in redundant or cls in seen:
            continue

