    """Return attribute names and descriptions defined by interface."""
    if not isinstance(all, bool):
        raise TypeError(f"'all' must be a bool, got {type(all).__name__}")
    attribute_map = {}
    classes = [self.__class__] if not all else reversed(self.__class__.mro())
    for cls in classes:
        for name, obj in cls.__dict__.items():
            # Skip private or special attributes
            if name.startswith('_'):
                continue
            # Skip methods and callable objects
            if callable(obj):
                continue
            # Determine description
            if isinstance(obj, property):
                # For properties, use the getter docstring if available
                desc = obj.fget.__doc__ if obj.fget is not None else ''
            else:
                # Default to the object's __doc__ if it exists
                desc = getattr(obj, "__doc__", "") or ""
            attribute_map[name] = desc
    return attribute_map<|return|>

