    # If no explicit INTERFACE attribute exists, fall back to the
    # instance's own attributes.  This helps in cases where an
    # interface hasn't been set up as a class attribute.
    if interface is None:
        return list(self.__dict__.keys())

    # The interface can be either a mapping (dict) or an iterable of
    # names.  Normalise it to a list of names.
    if isinstance(interface, dict):
        iface_names = list(interface.keys())
    else:
        try:
            iface_names = list(interface)
        except TypeError:
            iface_names = []

    if not all:
        return iface_names

    # When all=True we look up the entire MRO and combine any
    # interface names found.  The derived class's names take
    # precedence, but we still include any from base classes.
    all_names = set(iface_names)
    for base in cls.__mro__[1:]:
        base_interface = getattr(base, 'INTERFACE', None)
        if base_interface:
            if isinstance(base_interface, dict):
                all_names.update(base_interface.keys())
            else:
                try:
                    all_names.update(base_interface)
                except TypeError:
                    pass

    return list(all_names)<|return|>

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if sequence is None:
        return output

    # Try to iterate over the input; if it isn't iterable, treat it as a single item
    try:
        iterator = iter(sequence)
    except TypeError:
        output.append(sequence)
        return output

    for item in iterator:
        # Flatten nested lists or tuples (but leave strings intact)
        if isinstance(item, (list, tuple)) and not isinstance(item, (str, bytes)):
            _normalizeargs(item, output)
        else:
            output.append(item)

