    if isinstance(sequence, (list, tuple)):
        for item in sequence:
            if item is None:
                continue
            # Handle tuple: (DeclClass, (args...), kwargs)
            if isinstance(item, tuple):
                cls = item[0]
                # Separate args and kwargs if present
                if len(item) == 1:
                    args, kwargs = (), {}
                elif len(item) == 2:
                    args, kwargs = item[1], {}
                else:
                    # Assume last element could be dict of kwargs
                    if isinstance(item[-1], dict):
                        args = tuple(item[1:-1]) if len(item) > 2 else ()
                        kwargs = item[-1]
                    else:
                        args = tuple(item[1:]) if len(item) > 1 else ()
                        kwargs = {}
                try:
                    instance = cls(*args, **kwargs)
                except Exception as exc:
                    raise ValueError(f"Could not instantiate declaration from tuple {item}") from exc
                output.append(instance)
            else:
                # If item is already a declaration-like object, add directly
                output.append(item)
