    # Helper to determine if an object is a "sequence" that should be expanded.
    def _is_expandable(obj):
        return isinstance(obj, (list, tuple, set)) and not isinstance(obj, (str, bytes, bytearray))

    for item in sequence:
        if item is None:
            # Skip empty markers
