    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    # Validate separator
    if not isinstance(separator, str):
        raise TypeError("separator must be a string")

    # Ensure the graph has points
    if not hasattr(self, "points"):
        raise AttributeError("Graph object has no 'points' attribute")

    rows = []

    # Handle header
    if header is not None:
        if isinstance(header, (list, tuple)):
            # Join header elements with separator
            header_str = separator.join(map(str, header))
        else:
            header_str = str(header)
        rows.append(header_str)

    for point in self.points:
        # Distinguish the coordinate/value structure
        coords = None
        val = None

        if isinstance(point, (list, tuple)):
            if len(point) == 0:
                continue  # skip empty point
            coords = point[0]
            if len(point) > 1:
                val = point[1]
        else:
            # Try to introspect the point object
            if hasattr(point, "coordinates"):
                coords = point.coordinates
            elif hasattr(point, "coord"):
                coords = point.coord
            else:
                coords = point
            if hasattr(point, "value"):
                val = point.value
            elif hasattr(point, "values"):
                val = point.values

        # Convert coordinates to string, handling iterables
        if hasattr(coords, "__iter__") and not isinstance(coords, (str, bytes)):
