    lines = []
    if header is not None:
        lines.append(str(header))

    points_iter = getattr(self, "points", None)
    if points_iter is None:
        points_iter = self

    for point in points_iter:
        try:
            coords, value = point
        except Exception:
            coords, value = point, None

        if isinstance(coords, (str, bytes)):
            coord_parts = [str(coords)]
        else:
            try:
                coord_parts = [str(c) for c in coords]
            except Exception:
                coord_parts = [str(coords)]

        line = separator.join(coord_parts)

        if value is not None:
            if isinstance(value, (list, tuple)) and not isinstance(value, str):
                val_parts = [str(v) for v in value]
                line += separator + separator.join(val_parts)
            else:
                line += separator + str(value)

        lines.append(line)

    csv = "\n".join(lines)
    if csv:
        csv += "\n"
