    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # ensure inputs are sequences with matching dimensions
    try:
        n_bins = len(bins)
        n_edges = len(edges)
    except Exception as err:
        raise TypeError("bins and edges must be sequence-like objects") from err

    if n_edges != n_bins + 1:
        raise ValueError("Number of edges must be exactly one greater than number of bins")

    total = 0.0
    for i, bin_val in enumerate(bins):
        try:
            width = float(edges[i + 1]) - float(edges[i])
        except Exception as e:
            raise TypeError("edges must contain numeric values") from e

        try:
