        except Exception as e:
            raise TypeError("bins must contain numeric values") from e

    return total<|return|>

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Validate inputs
    if not isinstance(bins, (list, tuple)):
        raise TypeError('bins must be a sequence')
    if not isinstance(edges, (list, tuple)):
        raise TypeError('edges must be a sequence')
    if len(bins) + 1 != len(edges):
        raise ValueError('The number of edges must be one more than the number of bins')

    # Ensure edges are non‑decreasing
    for i in range(len(edges) - 1):
        if edges[i + 1] < edges[i]:
            raise ValueError(f'edges must be non-decreasing; edge {i + 1} < edge {i}')

    total = 0.0
    for bin_val, left, right in zip(bins, edges[:-1], edges[1:]):
        try:
            width = float(right) - float(left)
            val = float(bin_val)
        except Exception as exc:
            raise TypeError('Bins and edges must contain numeric values') from exc
        total += val * width

    return total<|return|>

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # ensure bins and edges are iterable
    try:
        bins_iter = list(bins)
        edges_iter = list(edges)
    except TypeError as exc:
        raise TypeError("bins and edges must be iterable") from exc

    n_bins = len(bins_iter)
    if n_bins == 0:
        return 0.0

    if len(edges_iter) != n_bins + 1:
        raise ValueError("edges must contain one more element than bins")

    total = 0.0
    for i, (b, e_start, e_end) in enumerate(zip(bins_iter, edges_iter, edges_iter[1:])):
        try:
            width = float(e_end) - float(e_start)
            if width <= 0:
                raise ValueError(f"Edge width must be positive, got {width} at index {i}")
            total += float(b) * width
        except (TypeError, ValueError) as exc:
            raise ValueError(f"Invalid numeric value at index {i}") from exc

    return total
