                for level, msgs in data.items():
                    if isinstance(msgs, (list, tuple)):
                        for m in msgs:
                            entries.append((level, m))
                    else:
                        entries.append((level, msgs))
            elif isinstance(data, (list, tuple, set)):
                # list/tuple/set of entries (each may be tuple or string)
                entries.extend(data)
            else:
                # try to iterate over it
                try:
                    entries.extend(list(data))
