    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    import collections
    errors = []

    # Basic type checking
    if not isinstance(inventory, collections.Mapping):
        raise TypeError("inventory must be a mapping (dictionary-like) object")

    # Extract and validate specification version if requested
    if extract_spec_version:
        type_value = inventory.get("type")
        if isinstance(type_value, str):
            # Accept only dot-separated digits, e.g. "3.1" or "3.1.2"
            parts = type_value.split(".")
            if all(part.isdigit() for part in parts) and parts:
                self.spec_version = type_value
            else:
                if getattr(self, "spec_version", None) is None:
                    errors.append("Invalid 'type' field for spec_version")
        else:
            if getattr(self, "spec_version", None) is None:
                errors.append("Missing 'type' field for spec_version")

    # Validate the structure of the inventory
    docs = inventory.get("documents")
    if docs is None:
        errors.append("Missing 'documents' key in inventory")
    elif not isinstance(docs, list):
        errors.append("'documents' must be a list")
    else:
        seen_ids = set()
        for idx, doc in enumerate(docs):
            if not isinstance(doc, collections.Mapping):
                errors.append(f"Element at index {idx} in 'documents' is not a mapping")
                continue
            doc_id = doc.get("id")
            if doc_id is None:
                errors.append(f"Document at index {idx} missing required 'id' field")
                continue
            if doc_id in seen_ids:
                errors.append(f"Duplicate document id '{doc_id}' found at index {idx}")
            else:
                seen_ids.add(doc_id)

    # If any errors were collected, raise an exception
