    for key, file_desc in (manifest_files.items() if isinstance(manifest_files, dict)
                           else enumerate(manifest_files)):
        # Expect each file descriptor to be a mapping that may contain a 'digest' key
        if isinstance(file_desc, dict) and 'digest' in file_desc:
            digest = file_desc['digest']
            if not isinstance(digest, str):
                raise ValueError(f"Digest value for file {key} must be a string")
            required_digests.add(digest)

    # Check that every required digest is used
    for digest in required_digests:
        if digest not in digests_used:
            raise ValueError(f"Required digest '{digest}' for a file in the manifest "
                             f"has not been used during processing")

    # Additionally, ensure that no digest is used that is not present in the manifest
    for digest in digests_used:
        if digest not in required_digests:
            raise ValueError(f"Digest '{digest}' was used but is not declared "
                             f"in the manifest")

    # If all checks pass, return True
    return True<|return|>

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Collect digests from the manifest.  If ``manifest_files`` is a mapping
    # (e.g. file_name -> digest) we extract the values; otherwise we assume it
    # is already an iterable of digests.
    try:
        manifest_digests = {v for _, v in manifest_files.items()}
    except AttributeError:
        manifest_digests = set(manifest_files)

    # Normalise the set of digests that are expected to be used.
    if isinstance(digests_used, (list, tuple)):
        digests_used = set(digests_used)
    elif not isinstance(digests_used, set):
        # Allow any iterable; convert to a set.
        digests_used = set(digests_used)

    # Identify mismatches between the two collections.
    missing_from_used = manifest_digests - digests_used
    missing_from_manifest = digests_used - manifest_digests

    # If any discrepancies are found, raise a ValueError with a helpful
    # message.  Otherwise, simply return True.
    errors = []
    if missing_from_used:
        errors.append(
            f"Digests present in manifest but not used: {sorted(missing_from_used)}"
        )
    if missing_from_manifest:
        errors.append(
            f"Digests used but not present in manifest: {sorted(missing_from_manifest)}"
        )

    if errors:
        raise ValueError("; ".join(errors))
    return True<|return|>

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Validate inputs
    if manifest_files is None:
        raise ValueError("manifest_files must not be None")
    if digests_used is None:
        raise ValueError("digests_used must not be None")

    # Convert digests_used to a set of strings, handling different iterable types
    try:
        used_set = set(digests_used)
    except Exception as exc:
        raise ValueError(f"Unable to convert digests_used to a set: {exc}") from exc

    # Determine the set of digests present in the manifest.
    # Support manifest_files being a dict mapping digest -> file info,
    # or an iterable of tuples where the first element is the digest.
    if isinstance(manifest_files, dict):
        manifest_digests = set(manifest_files.keys())
    else:
        try:
            manifest_digests = {digest for digest, *_ in manifest_files}
        except Exception:
            raise ValueError("manifest_files must be a dict or iterable of (digest, ...) tuples")

    # Check that every used digest is present in the manifest.
    missing = used_set - manifest_digests
    if missing:
        missing_str = ", ".join(sorted(missing))
        raise ValueError(
            f"The following digests are used but are not listed in the manifest: {missing_str}"
        )

    # Optionally warn if the manifest contains digests that are not used.
    unused = manifest_digests - used_set
    if unused:
        unused_str = ", ".join(sorted(unused))
        # Use warnings module for deprecation warning style
        import warnings
        warnings.warn(
            f"The following digests are present in the manifest but are not used: {unused_str}",
            RuntimeWarning,
        )<|return|>

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Ensure prior is of the same concrete type or compatible with self
        if not isinstance(prior, type(self)):
            raise ValueError("prior must be an instance of the same InventoryValidator type as self")

        # Helper to fetch a comparable version attribute
        def _get_version(obj):
            # Commonly used attribute names for version
            for key in ("version", "inventory_version", "ver", "rev"):
                if hasattr(obj, key):
                    return getattr(obj, key)
            # Try to fetch from dict if available
            if hasattr(obj, "__dict__"):
                for key in ("version", "inventory_version", "ver", "rev"):
                    if key in obj.__dict__:
                        return obj.__dict__[key]
            # No recognisable version attribute found
            return None

        self_version = _get_version(self)
        prior_version = _get_version(prior)

        if self_version is None or prior_version is None:
            raise ValueError("Both inventories must expose a comparable 'version' attribute")

        try:
            # Attempt natural ordering; if objects are not directly comparable, this will raise
            if prior_version >= self_version:
                raise ValueError(f"Provided prior version '{prior_version}' is not older than current version '{self_version}'.")
        except TypeError:
            # If versions cannot be compared natively, attempt string comparison
            try:
                if str(prior_version) >= str(self_version):
                    raise ValueError(f"Provided prior version '{prior_version}' is not older than current version '{self_version}'.")
            except Exception as exc:
                raise ValueError(f"Unable to compare inventory versions: {exc}")

        # Optional metadata consistency checks (e.g., same identifier)
        def _get_id(obj):
            for key in ("id", "identifier", "inventory_id"):
                if hasattr(obj, key):
                    return getattr(obj, key)
            if hasattr(obj, "__dict__") and "id" in obj.__dict__:
                return obj.__dict__["id"]
            return None

        self_id = _get_id(self)
        prior_id = _get_id(prior)

        if self_id is not None and prior_id is not None and self_id != prior_id:
            raise ValueError(f"Inventory IDs must match: self.id={self_id} vs prior.id={prior_id}")

        # All checks passed
        return True<|return|>

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Basic type check
        if not isinstance(prior, InventoryValidator):
            raise TypeError("prior must be an InventoryValidator instance")

        # Ensure same inventory id if present
        if hasattr(self, "id") and hasattr(prior, "id"):
            if self.id != prior.id:
                raise ValueError(f"Inventory IDs differ: {self.id} vs {prior.id}")

        # Ensure current inventory is newer than prior
        self_version = getattr(self, "version", None)
        prior_version = getattr(prior, "version", None)
        if self_version is not None and prior_version is not None:
            try:
                if self_version <= prior_version:
                    raise ValueError(f"Current inventory version ({self_version}) is not newer than prior version ({prior_version})")
            except TypeError:
                # Cannot compare non-comparable types, ignore this check
                pass

        # Ensure prior's items are a subset of current inventory's items
        self_items = getattr(self, "items", None)
        prior_items = getattr(prior, "items", None)
        if isinstance(self_items, dict) and isinstance(prior_items, dict):
            for key, value in prior_items.items():
                if key not in self_items:
                    raise ValueError(f"Key '{key}' from prior inventory missing in current inventory")
                if self_items[key] != value:
                    raise ValueError(f"Value mismatch for key '{key}' between inventories")

        # If all checks pass, validation succeeded
        return True
