def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is the correct type
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator instance")

    # Compare inventory identifiers if they exist
    self_id = getattr(self, "id", None)
    prior_id = getattr(prior, "id", None)
    if self_id is not None and prior_id is not None and self_id != prior_id:
        raise ValueError(f"Inventory id mismatch: current id '{self_id}' vs prior id '{prior_id}'")

    # Ensure both inventories have a version attribute
    self_version = getattr(self, "version", None)
    prior_version = getattr(prior, "version", None)
    if self_version is None or prior_version is None:
        raise ValueError("Both inventories must have a 'version' attribute")

    # The current inventory must be newer than the prior
    if self_version <= prior_version:
        raise ValueError(f"Current inventory version ({self_version}) is not newer than prior version ({prior_version})")

    # Optionally ensure that the current inventory contains all items from the prior
    prior_items = getattr(prior, "items", None)
    current_items = getattr(self, "items", None)
    if prior_items is not None and current_items is not None:
        try:
            if isinstance(prior_items, dict):
                for key in prior_items:
                    if key not in current_items:
                        raise ValueError(f"Prior inventory has item key '{key}' not present in current inventory")
            else:
                for item in prior_items:
                    if item not in current_items:
                        raise ValueError(f"Prior inventory contains item '{item}' not present in current inventory")
        except TypeError:
            # If items are not iterable, skip this check
            pass

    # If all checks pass, validation succeeds
    return True<|return|>

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Ensure prior is an instance of the same class
        if not isinstance(prior, InventoryValidator):
            raise TypeError(f"Expected a InventoryValidator instance, got {type(prior).__name__}")

        # Both inventories must expose a 'version' attribute
        if not hasattr(self, "version") or not hasattr(prior, "version"):
            raise AttributeError("Both inventories must provide a 'version' attribute")

        # Helper to parse version strings or tuples into comparable tuples of ints
        def _parse_version(v):
            if isinstance(v, str):
                v_clean = v.lstrip("vV")
                parts = v_clean.split(".")
                try:
                    return tuple(int(p) for p in parts if p.isdigit())
                except Exception:
                    pass
            if isinstance(v, (list, tuple)):
                try:
                    return tuple(int(p) for p in v)
                except Exception:
                    pass
            raise ValueError(f"Unrecognised version format {v!r}")

        ver_self = _parse_version(self.version)
        ver_prior = _parse_version(prior.version)

        # Prior must be strictly older
        if ver_prior >= ver_self:
            raise ValueError(
                f"Prior version {prior.version!r} must be older than current version {self.version!r}"
            )

        # Optional sanity check: inventory types should match
        if hasattr(self, "type") and hasattr(prior, "type") and self.type != prior.type:
            raise ValueError(
                f"Inventory type mismatch: current is {self.type!r}, prior is {prior.type!r}"
            )

        # Basic structural consistency check if inventories expose 'items' dicts
        if hasattr(self, "items") and hasattr(prior, "items"):
            missing = [k for k in self.items if k not in prior.items]
            if missing:
                raise ValueError(
                    f"The following items present in the current inventory are missing from prior: {missing}"
                )

        # If all checks pass, validation succeeds
        return True<|return|>

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type check
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator instance")
    # Self and prior must refer to different objects
    if self is prior:
        raise ValueError("prior cannot be the same instance as self")
    # Ensure inventories belong to the same catalogue
    if getattr(self, 'inventory_id', None) != getattr(prior, 'inventory_id', None):
        raise ValueError("inventory IDs differ; prior is not for this inventory")
    # Current inventory must be newer than prior
    self_version = getattr(self, 'version', None)
    prior_version = getattr(prior, 'version', None)
    if self_version is None or prior_version is None:
        raise ValueError("both inventories must have a version")
    try:
        if self_version <= prior_version:
            raise ValueError(
                f"current inventory version ({self_version}) "
                f"must be newer than prior version ({prior_version})"
            )
    except TypeError:
        raise ValueError("inventory versions are not comparable")
    # If item collections are present, current should not have fewer items
    if hasattr(self, 'items') and hasattr(prior, 'items'):
        if len(self.items) < len(prior.items):
            raise ValueError(
                "current inventory has fewer items than prior; "
                "cannot be a subsequent version"
            )
    # If all checks pass, nothing else to do
    return None<|return|>

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate inputs
    if not isinstance(inventory, dict):
        raise TypeError(f"inventory must be a dict, got {type(inventory).__name__}")
    if not isinstance(version, (str, int, float)):
        raise TypeError(f"version must be a str, int, or float, got {type(version).__name__}")

    result = {}

    for logical_path, data in inventory.items():
        if not isinstance(logical_path, str):
            # Skip non-string keys
            continue

        files_set = result.setdefault(logical_path, set())

        # Handle nested dict: logical_path -> { version: [files] }
        if isinstance(data, dict):
            # If there's a direct mapping from version to list/tuple/set of files
            if version in data:
                files_list = data[version]
                if isinstance(files_list, (list, tuple, set)):
                    files_set.update(files_list)
                elif isinstance(files_list, str):
                    files_set.add(files_list)
            else:
                # Check for 'content_files' subkey that might hold versions mapping
                content_map = data.get("content_files")
                if isinstance(content_map, dict) and version in content_map:
                    files_list = content_map[version]
                    if isinstance(files_list, (list, tuple, set)):
                        files_set.update(files_list)
                    elif isinstance(files_list, str):
                        files_set.add(files_list)

                # Handle possible list of versioned entries
                if isinstance(content_map, list):
                    for entry in content_map:
                        if isinstance(entry, dict):
                            if entry.get("version") == version:
                                files = entry.get("file") or entry.get("files")
                                if isinstance(files, (list, tuple, set)):
                                    files_set.update(files)
                                elif isinstance(files, str):
                                    files_set.add(files)

        # Handle list of entries directly under the logical path
        elif isinstance(data, list):
            for entry in data:
                if isinstance(entry, dict):
                    if entry.get("version") == version:
                        files = entry.get("file") or entry.get("files")
                        if isinstance(files, (list, tuple, set)):
                            files_set.update(files)
                        elif isinstance(files, str):
                            files_set.add(files)

        # If data is a single string or iterable of files
        elif isinstance(data, (list, tuple, set)):
            # Treat as a list of files for the current version
            files_set.update(data)

    # Remove any entries that ended up empty
    result = {lp: files for lp, files in result.items() if files}

    return result
<|return|>

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic validation
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict-like object")
    if not isinstance(version, (str, int)):
        raise TypeError("version must be a string or integer identifier")

    result = {}

    def _collect_entries(current, prefix=""):
        if isinstance(current, dict):
            for key, val in current.items():
                # If val is a mapping from version to file collections
                if isinstance(val, dict) and any(isinstance(v, (set, list, tuple)) for v in val.values()):
                    # Normal case: key is logical path, val maps versions to file sets
                    if key == "__state__" or key.lower() == "state":
                        # skip metadata keys
                        continue
                    # If val contains the target version
                    if version in val:
                        files = val[version]
                        if isinstance(files, (set, list, tuple)):
                            result[prefix + key] = set(files)
                        else:
                            # If not iterable, wrap into a set
                            result[prefix + key] = {files}
                    else:
                        # If no explicit entry for the version, try to find
                        # a default (e.g., the earliest version)
                        # Not required by spec; skip
                        pass
                else:
                    # Recurse into nested dictionaries which might hold logical paths
                    new_prefix = prefix + key + ("/" if prefix and key else "")
                    _collect_entries(val, new_prefix)
        elif isinstance(current, (list, tuple)):
            for item in current:
                _collect_entries(item, prefix)

    _collect_entries(inventory)

    return result<|return|>

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: ``logical_path_in_state -> set(content_files)``.

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, (dict, list)):
        raise ValueError("inventory must be a dict or list")
    if not isinstance(version, str):
        raise ValueError("version must be a string")

    result = {}

    def add_entry(logical, content):
        if not logical or not content:
            return
        result.setdefault(logical, set()).add(content)

    # Helper to process a single entry dict
    def process_entry(entry):
        if not isinstance(entry, dict):
            return
        # Prefer state path if available, fallback to logical_path
        logical = entry.get("state_path") or entry.get("logical_path")
        content = entry.get("content_file") or entry.get("file") or entry.get("path")
        entry_version = entry.get("version")
        if entry_version == version:
            add_entry(logical, content)

    # Inventory can be a dict mapping logical_path -> details,
    # a dict with key 'files' containing a list, or a list of entries.
    if isinstance(inventory, dict):
        # Case 1: list under 'files'
        if "files" in inventory:
            files = inventory["files"]
            if isinstance(files, list):
                for f in files:
                    process_entry(f)
            else:
                raise ValueError("inventory['files'] must be a list")
        else:
            # Case 2: top-level mapping logical_path -> details
            for logical_path, details in inventory.items():
                if isinstance(details, dict):
                    # Treat as a single entry with possible multiple entries nested
                    if "entries" in details and isinstance(details["entries"], list):
                        for sub in details["entries"]:
                            sub_copy = sub.copy()
                            sub_copy.setdefault("logical_path", logical_path)
                            process_entry(sub_copy)
                    else:
                        # Single entry
                        details_copy = details.copy()
                        details_copy.setdefault("logical_path", logical_path)
                        process_entry(details_copy)
                elif isinstance(details, list):
                    for sub in details:
                        sub_copy = sub.copy()
                        sub_copy.setdefault("logical_path", logical_path)
                        process_entry(sub_copy)
                else:
                    continue
    elif isinstance(inventory, list):
        for entry in inventory:
            process_entry(entry)
    else:
        raise ValueError("Unsupported inventory format")

    return result<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(manifest_files, (list, set, tuple)):
        raise ValueError("manifest_files must be a list, tuple or set of file names")

    # Convert manifest to a set for fast lookup
    manifest_set = set(manifest_files)

    # Normalise the fixity block into a list of (file, checksum) tuples
    if isinstance(fixity, dict):
        # Expected format: {filename: checksum, ...}
        entries = list(fixity.items())
    elif isinstance(fixity, (list, tuple)):
        # Expected format: [{ 'file': '...', 'checksum': '...' }, ...]
        entries = []
        for item in fixity:
            if not isinstance(item, dict):
                raise ValueError("Each entry in the fixity list must be a dict")
            file_ref = item.get('file')
            checksum = item.get('checksum')
            entries.append((file_ref, checksum))
    else:
        raise ValueError("Fixity block must be a dict or a list of dicts")

    seen_files = set()
    for file_ref, checksum in entries:
        if file_ref is None:
            raise ValueError("A fixity entry is missing the required 'file' field")

        if file_ref in seen_files:
            raise ValueError(f"Duplicate entry for file {file_ref!r} in fixity block")
        seen_files.add(file_ref)

        if file_ref not in manifest_set:
            raise ValueError(f"File {file_ref!r} referenced in fixity block is not present in the manifest")

        if checksum is None or not isinstance(checksum, str):
            raise ValueError(f"Checksum for file {file_ref!r} must be a non‑empty string")

    # If all checks passed, nothing to return (successful validation)
    return True<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, list):
        raise TypeError("fixity must be a list of file entries")
    if not isinstance(manifest_files, (list, set)):
        raise TypeError("manifest_files must be a list or set of file names")

    manifest_set = set(manifest_files)

    seen_files = set()

    for idx, entry in enumerate(fixity):
        if not isinstance(entry, dict):
            raise ValueError(f"fixity entry at index {idx} must be a dict")
        if 'file' not in entry:
            raise ValueError(f"fixity entry at index {idx} missing 'file' key")
        if 'hash' not in entry:
            raise ValueError(f"fixity entry at index {idx} missing 'hash' key")

        file_name = entry['file']
        if file_name not in manifest_set:
            raise ValueError(f"fixity entry references unknown file '{file_name}'")

        if file_name in seen_files:
            raise ValueError(f"duplicate fixity entry for file '{file_name}'")
        seen_files.add(file_name)

    return True<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Collect set of files that are present in the manifest
    if isinstance(manifest_files, dict):
        manifest_set = set(manifest_files.keys())
    elif isinstance(manifest_files, (set, list, tuple)):
        manifest_set = set(manifest_files)
    else:
        raise ValueError("manifest_files must be a dict, set, list, or tuple of filenames")

    # Interpret the fixity block, which may be a dict mapping filenames to checksums
    # or a list of entries each containing a 'file' key.
    referenced_files = []

    if isinstance(fixity, dict):
        # Assume keys are filenames
        referenced_files = list(fixity.keys())
    elif isinstance(fixity, (list, tuple)):
        # Expect each element to be a mapping with a 'file' key
        for entry in fixity:
            if not isinstance(entry, dict):
                raise ValueError(f"Each entry in fixity list must be a dict; got {type(entry).__name__}")
            if 'file' not in entry:
                raise ValueError("Each entry in fixity list must contain a 'file' key")
            referenced_files.append(entry['file'])
    else:
        raise ValueError(f"Fixity must be a dict or list; got {type(fixity).__name__}")

    # Ensure that every referenced file exists in manifest
    for fname in referenced_files:
        if fname not in manifest_set:
            raise ValueError(f"File '{fname}' referenced in fixity block is not present in manifest")

    # Ensure no duplicate references in fixity block
    if len(set(referenced_files)) != len(referenced_files):
        raise ValueError("Duplicate file references found in fixity block")

    # If we reach here, the fixity block is considered valid
    return True<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and make sure that only files
    listed in the manifest are referenced.
    """
    # Ensure fixity is iterable
    if not hasattr(fixity, "__iter__"):
        raise TypeError("The 'fixity' argument must be an iterable of file entries")

    # Convert manifest_files to a set for fast membership tests
    try:
        manifest_set = set(manifest_files)
    except TypeError:
        raise TypeError("The 'manifest_files' argument must be an iterable of file identifiers")

    seen_files = set()

    for idx, entry in enumerate(fixity):
        # Try to extract a unique file identifier from each entry
        file_id = None
        if isinstance(entry, dict):
            for key in ("file_id", "id", "name", "href"):
                if key in entry:
                    file_id = entry[key]
