        seen_files.add(file_id)

        # Validate that essential structural attributes exist
        # (adjust keys depending on the implementation specifics)
        required_attrs = ("checksum", "hash", "algorithm")
        for attr in required_attrs:
            present = False
            if isinstance(entry, dict):
                present = attr in entry
