def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    if not isinstance(folder, str):
        raise TypeError("folder must be a string path")
    if not os.path.isdir(folder):
        raise ValueError(f"The specified folder does not exist or is not a directory: {folder}")

    grouped = {}
    try:
        for root, _, files in os.walk(folder):
            for filename in files:
                full_path = os.path.join(root, filename)
                stem, _ = os.path.splitext(filename)
                # Initialize list for this stem if not already present
                if stem not in grouped:
                    grouped[stem] = []
                grouped[stem].append(full_path)
    except Exception as e:
        # Catch any filesystem-related errors
        raise RuntimeError(f"Error while exploring folder {folder}: {e}") from e

    return grouped<|return|>

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package

    Returns
    -------
    dict
    """
    import os
    # Validate input
    if not isinstance(folder, (str, bytes)):
        raise TypeError("folder must be a string path")
    if not os.path.isdir(folder):
        raise FileNotFoundError(f"Folder '{folder}' does not exist or is not a directory")

    # Dictionary to hold data keyed by base name
    data = {}

    # Walk through the folder recursively
    for root, _dirs, files in os.walk(folder):
        for filename in files:
            # Skip hidden files if desired
            if filename.startswith('.'):
                continue

            file_path = os.path.join(root, filename)
            base, ext = os.path.splitext(filename)

            # Initialize entry if this base name hasn't been seen before
            if base not in data:
                data[base] = {'xml': None, 'files': []}

            if ext.lower() == '.xml':
                if data[base]['xml'] is not None:
                    raise ValueError(f"Multiple XML files found for base '{base}': "
                                     f"'{data[base]['xml']}' and '{file_path}'")
                data[base]['xml'] = file_path
            else:
                data[base]['files'].append(file_path)

    return data<|return|>

def _eval_file(prefix, file_path):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    filename : str
        filename
    file_folder : str
        file folder

    Returns
    -------
    dict
    """
    import os
    try:
        if not file_path:
            raise ValueError("file_path is required")
        if not os.path.isfile(file_path):
            raise FileNotFoundError(f"File not found: {file_path}")

        # Heuristic: look for specific tags in the XML
        file_type = None
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                for i, line in enumerate(f):
                    lower = line.lower()
                    if '<asset' in lower:
                        file_type = 'asset'
                        break
                    if '<rendition' in lower:
                        file_type = 'rendition'
                        break
                    if i > 200:  # limit reading to first 200 lines
                        break
        except (OSError, UnicodeDecodeError):
            # If reading fails, skip tag inspection
            pass

        # Fallback based on filename or directory names
        if file_type not in ('asset', 'rendition'):
            name = prefix.lower()
            if 'asset' in name:
                file_type = 'asset'
            elif 'rendition' in name:
                file_type = 'rendition'
            else:
                # Check parent directory
                dir_name = os.path.basename(os.path.dirname(file_path)).lower()
                if 'asset' in dir_name:
                    file_type = 'asset'
                elif 'rendition' in dir_name:
                    file_type = 'rendition'
                else:
                    file_type = 'unknown'

        result = {
            'prefix': prefix,
            'type': file_type,
            'address': file_path
        }
        return result

    except Exception as exc:
        # Return minimal info with error message
        return {
            'prefix': prefix,
            'type': None,
            'address': file_path,
            'error': str(exc)
        }<|return|>

