def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    import re

    text = issue.text if hasattr(issue, "text") else str(issue)
    s = text.strip().lower()
    tokens = re.split(r'\s+|[.,;:]', s)
    number = None
    suppl = False

    for token in tokens:
        if not token:
            continue

        if token in ("suppl", "spe", "supp", "supl"):
            suppl = True
            continue

        # Handle tokens like "suppl5", "supp5", "spe2", "s2"
        for prefix in ("suppl", "supp", "spe", "s"):
            if token.startswith(prefix):
                suppl = True
                numpart = token[len(prefix) :]
                if numpart.isdigit():
                    number = int(numpart)
                    break

        if number is not None:
            break

        if token.isdigit():
            if number is None:
                number = int(token)

    if number is None:
        # look for a number that follows the supplement keyword
        m = re.search(
            r"(suppl|spe|supp|supl)[\.\s]*([0-9]+)", s, re.IGNORECASE
        )
        if m:
            number = int(m.group(2))
            suppl = True

    return number, suppl<|return|>

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    # Base indent string
    base_indent = '  ' * indent
    parts = [f"{base_indent}{self.__class__.__name__}"]

    # Include simple attributes (excluding private ones)
    attrs = []
    for key, value in vars(self).items():
        if key.startswith('_') or value is None:
            continue
        if isinstance(value, (str, int, float, bool)):
            attrs.append(f"{key}={repr(value)}")
    if attrs:
        parts[0] += " " + ", ".join(attrs)

    # Debug info (optional)
    if debug:
        parts.append(f"{base_indent}# id: {id(self)}")

    # Add representation of children if any
    if not isinstance(self, (str, bytes)):
        try:
            for child in self:
                if hasattr(child, 'pretty'):
                    parts.append(child.pretty(indent + 1, debug))
                else:
                    # Fallback for objects that cannot pretty-print
                    child_repr = repr(child)
                    parts.append(f"{'  ' * (indent + 1)}{child_repr}")
        except TypeError:
            # Not iterable, nothing to do
            pass

    return "\n".join(parts)<|return|>

def pretty(self, indent=0, debug=False):
        """Return a pretty formatted representation of self."""
        from collections import deque

        if not isinstance(indent, int) or indent < 0:
            raise ValueError("indent must be a non‑negative integer")

        visited = set()
        lines = []
        q = deque([(self, indent)])

        try:
            while q:
                obj, level = q.popleft()
                if id(obj) in visited:
                    lines.append("  " * level + "(already visited)")
                    continue
                visited.add(id(obj))

                prefix = "  " * level
                if debug:
                    part = f"{prefix}{obj.__class__.__name__}"
                    if hasattr(obj, "id"):
                        part += f" (id={obj.id!r})"
                else:
                    part = prefix

                if hasattr(obj, "__dict__"):
                    attrs = ", ".join(f"{k}={v!r}" for k, v in obj.__dict__.items()
                                      if not k.startswith("_") and v is not None)
                    part += attrs
                else:
                    part += repr(obj)

                lines.append(part)

                # Get children if available
                children = []
                if hasattr(obj, "children"):
                    try:
                        children = list(obj.children)  # may be a generator
                    except TypeError:
                        pass
                if hasattr(obj, "items"):
                    try:
                        children.extend(list(obj.items))
                    except TypeError:
                        pass
                for child in reversed(children):
                    q.appendleft((child, level + 1))

            return "\n".join(lines)
        except Exception as exc:
            raise RuntimeError(f"Error while pretty‑printing {self!r}: {exc}") from exc<|return|>

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Helper to determine if two expressions are structurally equal
    def equal(e1, e2):
        return e1 == e2

    # Recursive simplification of a single expression
    def simplify(expr):
        # Base case: if expr is not a tuple (assumed leaf), return as is
        if not isinstance(expr, tuple) or len(expr) < 2:
            return expr

        op = expr[0]
        # Binary operators: 'and', 'or'
        if op in ('and', 'or'):
            left = simplify(expr[1])
            right = simplify(expr[2])

            # Absorption rules
            if op == 'and':
                # A & (A | B) = A
                if isinstance(right, tuple) and right[0] == 'or':
                    a, b = right[1], right[2]
                    if equal(left, a) or equal(left, b):
                        return left
