                if isinstance(left, tuple) and left[0] == 'or':
                    a, b = left[1], left[2]
                    if equal(right, a) or equal(right, b):
                        return right
                # Negative absorption: A & (~A | B) = A & B
                if isinstance(right, tuple) and right[0] == 'or':
                    if (isinstance(right[1], tuple) and right[1][0] == 'not' and equal(left, right[1][1])):
                        b = right[2]
                        return simplify(('and', left, b))
                    if (isinstance(right[2], tuple) and right[2][0] == 'not' and equal(left, right[2][1])):
                        b = right[1]
