                # Negative absorption: (~A | B) & A = A & B
                if isinstance(left, tuple) and left[0] == 'or':
                    if (isinstance(left[1], tuple) and left[1][0] == 'not' and equal(right, left[1][1])):
                        b = left[2]
                        return simplify(('and', right, b))
                    if (isinstance(left[2], tuple) and left[2][0] == 'not' and equal(right, left[2][1])):
                        b = left[1]
                        return simplify(('and', right, b))
            elif op == 'or':
                # A | (A & B) = A
                if isinstance(right, tuple) and right[0] == 'and':
                    a, b = right[1], right[2]
                    if equal(left, a) or equal(left, b):
