def get_versions():
    """Get version information or return default if unable to do so."""
    import sys
    from pathlib import Path
    result = {
        "package_version": "unknown",
        "git_revision": None,
        "dirty": False,
        "error": None,
    }

    # Try to determine the distribution name from the current package
    try:
        pkg_name = sys.modules[__name__].__package__
    except Exception:
        pkg_name = None

    # Attempt to fetch package metadata (Python 3.8+)
    try:
        import importlib.metadata as meta
    except Exception:
        try:
            # fallback for older Python versions
            import importlib_metadata as meta  # type: ignore
        except Exception:
            meta = None

    # Retrieve the package version
    try:
        if meta and pkg_name:
            # Use the distribution object if available
            dist = meta.distribution(pkg_name)
            result["package_version"] = dist.version
        elif meta and pkg_name:
            # Fallback to direct lookup
            result["package_version"] = meta.version(pkg_name)
    except Exception as e:
        result["error"] = f"Package version error: {e}"

    # Gather git information
    try:
        repo_root = Path(__file__).resolve().parent
        if (repo_root / ".git").exists():
            import subprocess

            # Get commit hash
            rev = subprocess.check_output(
                ["git", "rev-parse", "HEAD"], cwd=repo_root, text=True
            ).strip()
            result["git_revision"] = rev

            # Detect dirty status
            status = subprocess.check_output(
                ["git", "status", "--porcelain"], cwd=repo_root, text=True
            )
            result["dirty"] = bool(status.strip())
    except Exception as e:
        # Append git errors to the existing error message
        if result["error"]:
            result["error"] += f"; git error: {e}"
        else:
            result["error"] = f"git error: {e}"

    return result<|return|>

