def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess, os, shlex

    def _run_single(cmd, args, cwd, verbose, hide_stderr, env):
        if isinstance(cmd, str):
            cmd_list = shlex.split(cmd)
        else:
            cmd_list = list(cmd)
        arg_list = list(args) if args else []
        full_cmd = cmd_list + arg_list

        if verbose:
            print("Running command:", subprocess.list2cmdline(full_cmd), "in", cwd or os.getcwd())

        env_copy = os.environ.copy()
        if env:
            env_copy.update(env)

        try:
            result = subprocess.run(
                full_cmd,
                cwd=cwd,
                env=env_copy,
                capture_output=True,
                text=True
            )
            stdout = result.stdout
            stderr = result.stderr if not hide_stderr else ""
            return {
                "returncode": result.returncode,
                "stdout": stdout,
                "stderr": stderr,
                "cmd": full_cmd
            }
        except FileNotFoundError as e:
            return {
                "returncode": -1,
                "stdout": "",
                "stderr": str(e),
                "cmd": full_cmd
            }
        except Exception as e:
            return {
                "returncode": -1,
                "stdout": "",
                "stderr": f"Unexpected error: {e}",
                "cmd": full_cmd
            }

    if isinstance(commands, (list, tuple)):
        results = []
        for c in commands:
            res = _run_single(c, args, cwd, verbose, hide_stderr, env)
            results.append(res)
            if res["returncode"] != 0:
                break
        return results
    else:
        return _run_single(commands, args, cwd, verbose, hide_stderr, env)<|return|>

