def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    def _traverse(obj):
        nonlocal num_objects, good_objects

        num_objects += 1
        valid = True

        # Validate the object itself, if requested
        if validate_objects:
            validate_method = getattr(obj, 'validate', None)
            if callable(validate_method):
                try:
                    if not validate_method():
                        valid = False
                        if show_warnings:
                            print(f"[WARN] Validation failed for object: {obj!r}")
                except Exception as e:
                    valid = False
                    if show_warnings:
                        print(f"[WARN] Exception during validation of {obj!r}: {e}")
            else:
                if show_warnings:
                    print(f"[WARN] No validate() method for object: {obj!r}")

        # Check digests, if requested
        if check_digests:
            digest_method = getattr(obj, 'verify_digest', None)
            if callable(digest_method):
                try:
                    if not digest_method():
                        valid = False
                        if show_warnings:
                            print(f"[WARN] Digest check failed for object: {obj!r}")
                except Exception as e:
                    valid = False
                    if show_warnings:
                        print(f"[WARN] Exception during digest check of {obj!r}: {e}")
            else:
                if show_warnings:
                    print(f"[WARN] No verify_digest() method for object: {obj!r}")

        if valid:
            good_objects += 1

        # Recursively validate child elements
        children = getattr(obj, 'children', None)
        if children is None:
            children = getattr(obj, 'elements', None)
        if children:
            for child in children:
                _traverse(child)

    _traverse(self)
    return num_objects, good_objects<|return|>

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        # Counters
        num_objects = 0
        good_objects = 0

        def _validate(obj):
            nonlocal num_objects, good_objects
            num_objects += 1
            ok = True

            # Validate the object itself if requested
            if validate_objects:
                try:
                    if hasattr(obj, 'validate'):
                        # Some objects return a boolean status
                        result = obj.validate()
                        if result is False:
                            ok = False
                    elif hasattr(obj, 'is_valid'):
                        if not getattr(obj, 'is_valid', False):
                            ok = False
                    # If the object has no validate/is_valid method we consider it fine
                except Exception as exc:
                    if show_warnings:
                        print(f"Warning: validation failed for {obj!r}: {exc}")
                    ok = False

            # Verify digests if requested
            if check_digests:
                try:
                    if hasattr(obj, 'verify_digest'):
                        result = obj.verify_digest()
                        if result is False:
                            ok = False
                except Exception as exc:
                    if show_warnings:
                        print(f"Warning: digest check failed for {obj!r}: {exc}")
                    ok = False

            if ok:
                good_objects += 1

            # Recursively validate children if the object is iterable
            try:
                # Avoid iterating over plain bytes/str or objects that are not containers
                if isinstance(obj, (str, bytes)):
                    return
                # For mappings, iterate over values
                if isinstance(obj, dict):
                    iterable = obj.values()
                else:
                    iterable = obj
                for child in iterable:
                    # Avoid infinite recursion on self references
                    if child is obj:
                        continue
                    _validate(child)
            except Exception:
                # if the object cannot be iterated, ignore and continue
                pass

        # Start recursion from self
        _validate(self)
        return num_objects, good_objects<|return|>

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Counters for objects processed and those that passed validation
    num_objects = 0
    good_objects = 0

    def _traverse(obj):
        nonlocal num_objects, good_objects
        num_objects += 1
        is_valid = True

        # Validate object itself if requested
        if validate_objects:
            try:
                # Assume objects have a validate() method that returns a bool.
                if hasattr(obj, "validate"):
                    result = obj.validate()
                    if result is not None:
                        is_valid = bool(result)
                else:
                    # If no explicit validate method, consider valid by default
                    is_valid = True
            except Exception:
                is_valid = False

        # Optional digest check
        if check_digests and is_valid:
            try:
                # Some objects may provide a 'digests' dict/list/tuple
                if hasattr(obj, "digests"):
                    digests = obj.digests
                    if isinstance(digests, dict):
                        if not all(digests.values()):
                            is_valid = False
                    elif isinstance(digests, (list, tuple)):
                        if not all(digests):
                            is_valid = False
                elif hasattr(obj, "digest"):
                    # Single digest value
                    if not obj.digest:
                        is_valid = False
            except Exception:
                is_valid = False

        if is_valid:
            good_objects += 1
        elif show_warnings:
            try:
                obj_repr = repr(obj)
            except Exception:
                obj_repr = str(obj)
            print(f"Validation failed for object {obj_repr}")

        # Recurse into children if iterable
        if hasattr(obj, "__iter__"):
            try:
                for child in obj:
                    _traverse(child)
            except Exception:
                # If iteration fails, just skip children
                pass

    # Start traversal from the root itself
    _traverse(self)
    return num_objects, good_objects<|return|>

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    total = 0
    good = 0

    # Helper stack for depth‑first traversal, avoiding recursion
    stack = [self]
    while stack:
        obj = stack.pop()
        # Skip the root object itself
        if obj is self:
            continue

        total += 1

        # Determine validity of the object
        valid = True
        if validate_objects:
            try:
                # If the object has a validate method, call it.
                if hasattr(obj, "validate") and callable(obj.validate):
                    result = obj.validate()
                    # If validate returns False, treat as invalid
                    if result is False:
                        valid = False
            except Exception:
                valid = False

        digest_valid = True
        if check_digests:
            try:
                # Try to obtain the expected digest
                expected = getattr(obj, "digest", None)
                if expected is None and hasattr(obj, "compute_digest"):
                    expected = obj.compute_digest()
                # Compute the actual digest if possible
                if expected is not None:
                    actual = getattr(obj, "digest", None)
                    if actual is None and hasattr(obj, "compute_digest"):
                        actual = obj.compute_digest()
                    if actual != expected:
                        digest_valid = False
            except Exception:
                digest_valid = False

        if valid and digest_valid:
            good += 1
        else:
            if show_warnings:
                obj_id = getattr(obj, "id", None)
                obj_type = type(obj).__name__
                parts = [f"{obj_type}"]
                if obj_id:
                    parts.append(f"id={obj_id}")
                if not valid:
                    parts.append("validation failed")
                if not digest_valid:
                    parts.append("digest mismatch")
                print("Warning:", ", ".join(parts))

        # Add children to the stack if the object is iterable
        try:
            children = list(obj)
            stack.extend(children)
        except Exception:
            # Not iterable, nothing to do
            pass

    return total, good<|return|>

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        num_objects = 0
        good_objects = 0
        # We'll perform a depth‑first traversal using a stack to avoid recursion limits.
        stack = [self]
        seen = set()
        while stack:
            obj = stack.pop()
            obj_id = id(obj)
            if obj_id in seen:
                continue
            seen.add(obj_id)

            # Each object is counted regardless of validity.
            num_objects += 1
            obj_valid = True
            try:
                # Validate the object itself if requested.
                if validate_objects:
                    if hasattr(obj, "validate") and callable(obj.validate):
                        obj_valid = obj.validate()
                    elif hasattr(obj, "is_valid"):
                        # Allow a simple boolean attribute.
                        obj_valid = bool(obj.is_valid)

                # Optionally perform a digest check.
                if check_digests and hasattr(obj, "check_digest") and callable(obj.check_digest):
                    if not obj.check_digest():
                        obj_valid = False
            except Exception as exc:
                # If validation fails we regard the object as invalid.
                obj_valid = False
                if show_warnings:
                    try:
                        from foilajson.logger import flog
                    except Exception:
                        flog = None
                    if flog:
                        flog.warning(f"Validation error for object {repr(obj)}: {exc}")

            if obj_valid:
                good_objects += 1

            # Add children to the stack if the object is iterable.
            if hasattr(obj, "__iter__"):
                try:
                    for child in obj:
                        # Skip iterator references such as self for containers.
                        if child is not None:
                            stack.append(child)
                except Exception:
                    # Child iteration failure should not abort the overall validation.
                    pass

        return num_objects, good_objects<|return|>

