def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    if not version:
        raise ValueError("version string is empty")
    parts = version.split('.')
    if not parts:
        raise ValueError("invalid version format")
    last = parts[-1]
    if not last.isdigit():
        raise ValueError(f"version segment '{last}' is not numeric")
    leading_len = len(last)
    try:
        new_num = int(last) + 1
    except Exception as exc:
        raise ValueError(f"cannot increment version segment '{last}'") from exc
    new_last = str(new_num).zfill(leading_len)
    return '.'.join(parts[:-1] + [new_last])<|return|>

