        raise TypeError(f"version must be a string, got {type(version).__name__}")
    if not version.isdigit():
        raise ValueError(f"Invalid version format: {version!r}; expected numeric string")
    # Compute next integer
    try:
        num = int(version)
    except OverflowError as exc:
        raise ValueError(f"Version numeric value too large: {version!r}") from exc
    next_num = num + 1
    # Preserve original length for zero-padded numbers
    orig_len = len(version)
    next_str = str(next_num)
    if len(next_str) <= orig_len:
        next_str = next_str.zfill(orig_len)
    return next_str<|return|>

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        import os
        import xml.etree.ElementTree as ET

        if not isinstance(version_dirs, (list, tuple)):
            raise TypeError("version_dirs must be a list or tuple of directory names")
        if not version_dirs:
            # nothing to validate
            return True

        # Helper to load inventory XML into a dict of {file_path: digest}
        def _load_inventory(inv_path):
            if not os.path.isfile(inv_path):
                raise FileNotFoundError(f"Inventory file not found: {inv_path}")
            try:
                tree = ET.parse(inv_path)
                root = tree.getroot()
            except ET.ParseError as e:
                raise ValueError(f"Invalid inventory XML at {inv_path}: {e}") from e
            inv_dict = {}
            for entry in root.findall('file'):
                path = entry.get('path')
                digest = entry.get('digest')
                if not path or not digest:
                    continue  # skip malformed entries
                inv_dict[path] = digest
            return inv_dict

        # Determine absolute root path for the document; fall back to current working dir
        base_path = getattr(self, 'docroot', None) or getattr(self, 'root_dir', None) or os.getcwd()

        # Root inventory (version 0)
        root_inventory_path = os.path.join(base_path, 'inventory.xml')
        try:
            root_inv = _load_inventory(root_inventory_path)
        except Exception as e:
            raise ValueError(f"Failed to load root inventory: {e}") from e

        cumulative_files = set()
        # Store differences: {version: {file: (root_digest, current_digest)}}
        self._different_digests = {}

        for idx, vdir in enumerate(version_dirs, start=1):
            # Assume the inventory file is named 'inventory.xml' in each version dir
            inv_path = os.path.join(base_path, vdir, 'inventory.xml')
            try:
                inv_dict = _load_inventory(inv_path)
            except Exception as e:
                raise ValueError(f"Failed to load inventory for version {vdir}: {e}") from e

            # Check that all previously seen files are present in this inventory
            missing = cumulative_files - set(inv_dict.keys())
            if missing:
                raise ValueError(f"Version {vdir} inventory missing files: {', '.join(sorted(missing))}")

            # Add new files from this inventory to cumulative set
            cumulative_files.update(inv_dict.keys())

            # Check for digest differences between this inventory and the root inventory
            diffs = {}
            for path, digest in inv_dict.items():
                root_digest = root_inv.get(path)
                if root_digest is None:
                    # New file added in this version; skip comparison
                    continue
                if digest != root_digest:
                    diffs[path] = (root_digest, digest)
            if diffs:
                self._different_digests[vdir] = diffs

        return True<|return|>

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import json

    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")

    # Store differences: {version_dir: {path: (root_digest, current_digest)}}
    self._different_digests = {}

    cumulative_keys = set()
    root_inventory = None

    for idx, dir_name in enumerate(version_dirs):
        if not isinstance(dir_name, str):
            raise TypeError(f"Each directory name must be a string, got {type(dir_name).__name__}")

        inventory_path = os.path.join(dir_name, "inventory.json")
        if not os.path.isfile(inventory_path):
            raise FileNotFoundError(f"Inventory file not found: {inventory_path}")

        try:
            with open(inventory_path, "r", encoding="utf-8") as f:
                inventory = json.load(f)
        except Exception as exc:
            raise ValueError(f"Failed to load inventory from {inventory_path}: {exc}")

        if not isinstance(inventory, dict):
            raise ValueError(f"Inventory in {inventory_path} should be a JSON object mapping paths to digests")

        # Root inventory is the first one
        if idx == 0:
            root_inventory = inventory.copy()
            cumulative_keys.update(inventory.keys())
        else:
            # Each subsequent inventory must contain all items up to this point
            missing = cumulative_keys - inventory.keys()
            if missing:
                missing_list = ", ".join(sorted(missing))
                raise ValueError(
                    f"Version '{dir_name}' inventory is missing entries from prior versions: {missing_list}"
                )
            # Record differences from root inventory
            diffs = {}
            for path, digest in inventory.items():
                root_digest = root_inventory.get(path)
                if root_digest is not None and root_digest != digest:
                    diffs[path] = (root_digest, digest)
            if diffs:
                self._different_digests[dir_name] = diffs

            cumulative_keys.update(inventory.keys())

    # Optionally return the differences dictionary for external use
    return self._different_digests)<|return|>

