    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    if unparsed_arguments is None:
        unparsed_arguments = []
    if subparsers is None:
        subparsers = {}
    parsed_results = {}
    remaining_lists = []

    # Try to parse all arguments with each subparser
    for name, parser in subparsers.items():
        try:
            args, remaining = parser.parse_known_args(unparsed_arguments)
        except Exception:
            # If parsing fails (unlikely for parse_known_args), fallback to empty namespace
            args = argparse.Namespace()
            remaining = list(unparsed_arguments)
        parsed_results[name] = args
        remaining_lists.append(remaining)

    # Determine arguments that were not claimed by ANY subparser
    if remaining_lists:
        # Start with the first list of remaining args
        unclaimed = set(remaining_lists[0])
        for rem in remaining_lists[1:]:
            unclaimed.intersection_update(rem)
        # Preserve the order of the original argument list
        final_remaining = [arg for arg in unparsed_arguments if arg in unclaimed]
    else:
        final_remaining = list(unparsed_arguments)

    return parsed_results, final_remaining<|return|>

