def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not isinstance(size, str):
        raise TypeError("size must be a string")
    s = size.strip()
    if not s:
        raise ValueError("empty size string")

    import re
    m = re.match(r'^(\d*\.?\d+|\.\d+)\s*([a-zA-Z]*)$', s)
    if not m:
        raise ValueError(f"invalid size format: {size!r}")

    number_str, unit = m.groups()
    try:
        number = float(number_str)
    except ValueError as exc:
        raise ValueError(f"invalid numeric value in size: {number_str!r}") from exc

    unit = unit.lower()
    if unit in ("", "b"):
        multiplier = 1
    elif unit.startswith("k"):
        multiplier = 10 ** 3
    elif unit.startswith("m"):
        multiplier = 10 ** 6
    elif unit.startswith("g"):
        multiplier = 10 ** 9
    elif unit.startswith("t"):
        multiplier = 10 ** 12
    elif unit.startswith("p"):
        multiplier = 10 ** 15
    else:
        raise ValueError(f"unknown unit in size: {unit!r}")

    return int(round(number * multiplier))
<|return|>

