    return list(seen)<|return|>

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate input types
    if not isinstance(string, str):
        raise TypeError(f"string must be of type str, got {type(string).__name__}")
    if not isinstance(alphabet, list) or not alphabet:
        raise ValueError("alphabet must be a non-empty list of single-character strings")

    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two distinct characters")

    # Build mapping from character to its integer value
    char_to_val = {}
    for idx, ch in enumerate(alphabet):
        if not isinstance(ch, str) or len(ch) != 1:
            raise ValueError(f"alphabet entries must be single characters, got {repr(ch)}")
        if ch in char_to_val:
            raise ValueError(f"duplicate character '{ch}' in alphabet")
        char_to_val[ch] = idx

    if string == "":
        raise ValueError("input string cannot be empty")

    result = 0
    for ch in string:
        if ch not in char_to_val:
            raise ValueError(f"character '{ch}' not found in alphabet")
        result = result * base + char_to_val[ch]

    return result
