def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys, os

    # Determine current platform if needed
    if platform == 'this':
        platform = 0 if os.name == 'nt' else 1

    if not isinstance(s, str):
        raise TypeError(f"s must be a str, not {type(s).__name__}")

    # Regex patterns for POSIX and Windows
    if platform == 1:  # POSIX
        # Group dq: double-quoted, sq: single-quoted, esc: escaped char, word: normal word
        pattern = re.compile(
            r'''(?:"(?P<dq>(?:\\.|[^"\\])*)"|'(?P<sq>(?:\\.|[^'\\])*)'|\\(?P<esc>.)|(?P<word>[^\s]+))'''
        )

        def unescape(seq):
            return re.sub(r'\\(.)', r'\1', seq)

    else:  # Windows/CMD
        # Group dq: double-quoted (including doubled quotes), word: normal word
        pattern = re.compile(
            r'''(?:"(?P<dq>(?:[^"]|"")*)"|(?P<word>[^\s]+))'''
        )

        def unescape(seq):
            return seq.replace('""', '"')

    # Edge case: empty string -> empty list
    if not s:
        return []

    tokens = []
    pos = 0
    for match in pattern.finditer(s):
        start, end = match.span()
        # Skip any whitespace between tokens
        if start > pos:
            # If there's only whitespace, it's fine; otherwise malformed string
            intervening = s[pos:start]
            if not intervening.isspace():
                raise ValueError(f"Malformed input at position {pos}: '{intervening}'")
        pos = end

        if match.group('dq') is not None:
            val = unescape(match.group('dq'))
        elif match.group('sq') is not None:
            val = unescape(match.group('sq'))
        elif match.group('esc') is not None:
            val = match.group('esc')
        elif match.group('word') is not None:
            val = match.group('word')
        else:
            continue  # Shouldn't happen
        tokens.append(val)

    # Any remaining trailing whitespace is ignored; any other characters would be an error
    if pos < len(s) and not s[pos:].isspace():
        raise ValueError(f"Trailing characters at end of input: '{s[pos:]}'")

    return tokens
<|return|>

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if not isinstance(s, str):
        raise TypeError(f"s must be a string, got {type(s).__name__}")
    # Resolve platform
    if platform == 'this':
        import sys
        if sys.platform.startswith('win'):
            platform = 0
        else:
            platform = 1
    if platform not in (0, 1):
        raise ValueError("platform must be 0 (Windows), 1 (POSIX) or 'this'")

    # POSIX: use shlex with posix=True
    if platform == 1:
        try:
            import shlex
            return shlex.split(s, posix=True)
        except Exception:
            # fallback: simple regex
            import re
            pattern = r'''(?:(?:\\.|[^\\\s])+|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*')'''
            tokens = re.findall(pattern, s)
            # strip surrounding quotes and unescape
            result = []
            for token in tokens:
                if (token[0] == token[-1] and token[0] in ('"', "'")):
                    token = token[1:-1]
                token = token.replace(r'\"', '"').replace(r"\'", "'").replace(r'\\', '\\')
                result.append(token)
            return result

    # Windows: custom parser
    tokens = []
    cur = []
    in_quote = False
    quote_char = ''
    i = 0
    length = len(s)
    while i < length:
        ch = s[i]
        if in_quote:
            if ch == '\\' and i + 1 < length:
                # Escape character inside quotes
                cur.append(s[i+1])
                i += 1
            elif ch == quote_char:
                in_quote = False
            else:
                cur.append(ch)
        else:
            if ch.isspace():
                if cur:
                    tokens.append(''.join(cur))
                    cur = []
            elif ch in ('"', "'"):
                in_quote = True
                quote_char = ch
            elif ch == '\\':
                # In Windows CMD, backslash escapes next character even outside quotes
                if i + 1 < length:
                    cur.append(s[i+1])
                    i += 1
                else:
                    cur.append('\\')
            else:
                cur.append(ch)
        i += 1
    if cur:
        tokens.append(''.join(cur))
    return tokens<|return|>

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast regex.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        import os
        platform = 0 if os.name == 'nt' else 1
    if platform not in (0, 1):
        raise ValueError("Invalid platform value; must be 0, 1, or 'this'")
    import shlex
    if not s:
        return []
    # shlex can be configured for POSIX or non-POSIX tokenisation
    lexer = shlex.shlex(s, posix=(platform == 1))
    lexer.whitespace_split = True
    lexer.commenters = ''
    try:
        return list(lexer)
    except ValueError as exc:
        # Preserve original error but provide context
        raise ValueError(f"Failed to split string: {exc}") from exc<|return|>

