def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    freq = frequency.strip()
    if not freq:
        raise ValueError('Cannot parse an empty frequency string')
    if freq.lower() == 'always':
        return None

    import re
    m = re.match(r'^\s*(\d+(?:\.\d+)?)\s*(\w+)\s*$', freq)
    if not m:
        raise ValueError(f'Unable to parse frequency: {frequency}')
    num_str, unit = m.group(1), m.group(2).lower()
    try:
        num = float(num_str)
    except ValueError:
        raise ValueError(f'Invalid number in frequency: {num_str}')

    unit_map = {
        'day': 'days', 'days': 'days',
        'hour': 'hours', 'hours': 'hours',
        'minute': 'minutes', 'minutes': 'minutes',
        'second': 'seconds', 'seconds': 'seconds',
        'week': 'weeks', 'weeks': 'weeks',
        'millisecond': 'milliseconds', 'milliseconds': 'milliseconds',
        'microsecond': 'microseconds', 'microseconds': 'microseconds',
    }
    if unit not in unit_map:
        raise ValueError(f'Invalid unit in frequency: {unit}')

    kwargs = {unit_map[unit]: num}
    return datetime.timedelta(**kwargs)<|return|>

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    freq_str = frequency.strip()
    if not freq_str:
        return None
    if freq_str.lower() == 'always':
        return None
    parts = freq_str.split()
    if len(parts) != 2:
        raise ValueError(f"Unable to parse frequency '{frequency}': expected a number and a unit")
    number_str, unit_str = parts
    try:
        number = float(number_str)
    except ValueError:
        raise ValueError(f"Unable to parse frequency '{frequency}': number part '{number_str}' is not numeric")
    unit_str = unit_str.lower().strip().rstrip(',')
    unit_map = {
        'day': 'days', 'days': 'days',
        'week': 'weeks', 'weeks': 'weeks',
        'hour': 'hours', 'hours': 'hours',
        'minute': 'minutes', 'minutes': 'minutes',
        'second': 'seconds', 'seconds': 'seconds',
    }
    if unit_str not in unit_map:
        raise ValueError(f"Unable to parse frequency '{frequency}': unit '{unit_str}' is not supported")
    kwargs = {unit_map[unit_str]: number}
    return datetime.timedelta(**kwargs)<|return|>

