def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not isinstance(host, str):
        return False
    try:
        # Resolve host to all possible addresses
        addrinfo = socket.getaddrinfo(host, None, socket.AF_UNSPEC, socket.SOCK_STREAM)
        for _, _, _, _, sockaddr in addrinfo:
            ip = sockaddr[0]
            # IPv4
            if ip.count('.') == 3:
                if ip == '127.0.0.1':
                    return True
            # IPv6
            if ip.lower() == '::1':
                return True
            # IPv6-mapped IPv4 address (e.g., ::ffff:127.0.0.1)
            if ip.lower().startswith('::ffff:'):
                mapped_ip = ip.split(':', 1)[1]
                if mapped_ip == '127.0.0.1':
                    return True
    except socket.gaierror:
        # If resolution fails, treat the input as a raw IP address
        ip = host
        if ip == '127.0.01':
            return True
        if ip.lower() == '::1':
            return True
        if ip.lower().startswith('::ffff:'):
            mapped_ip = ip.split(':', 1)[1]
            if mapped_ip == '127.0.0.1':
                return True
    return False<|return|>

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    try:
        addrinfo = socket.getaddrinfo(host, None)
    except (socket.gaierror, ValueError):
        return False

    for family, _, _, _, sockaddr in addrinfo:
        ip_addr = sockaddr[0]
        if family == socket.AF_INET:
            try:
                packed = socket.inet_aton(ip_addr)
                # Loopback IPv4 addresses start with 127
                if packed[0] == 127:
                    return True
            except OSError:
                continue
        elif family == socket.AF_INET6:
            try:
                packed = socket.inet_pton(socket.AF_INET6, ip_addr)
                # Loopback IPv6 address is all zero except last octet 1
                if packed == b'\x00' * 15 + b'\x01':
                    return True
            except OSError:
                continue
    return False<|return|>

