    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # Determine variable name and optional default based on the type of matcher
    name = None
    default = None

    # Matcher could be a tuple/list: (name, default?)
    if isinstance(matcher, (tuple, list)):
        if len(matcher) == 0:
            raise ValueError("Matcher tuple/list must contain at least the variable name")
        name = str(matcher[0])
        if len(matcher) >= 2:
            default = matcher[1]
    # Matcher could be a dict with keys 'name' and 'default'
    elif isinstance(matcher, dict):
        if 'name' not in matcher:
            raise ValueError("Matcher dict must contain a 'name' key")
        name = str(matcher['name'])
        default = matcher.get('default')
    # Matcher could be a string: either "NAME" or "NAME:default"
    elif isinstance(matcher, str):
        if ':' in matcher:
            parts = matcher.split(':', 1)
            name = parts[0]
            default = parts[1]
        else:
            name = matcher
    # Matcher could be a regex match object (fallback)
    elif hasattr(matcher, 'group'):
        try:
            name = matcher.group(1)
            if hasattr(matcher, 'groupdict') and 'default' in matcher.groupdict():
                default = matcher.group('default')
            else:
                # Try second group if available
                if matcher.lastindex and matcher.lastindex >= 2:
                    default = matcher.group(2)
        except Exception as e:
            raise ValueError(f"Unsupported matcher type: {type(matcher).__name__}") from e
    else:
        raise TypeError(f"Unsupported matcher type: {type(matcher).__name__}")

    if name is None:
        raise ValueError("Could not determine variable name from matcher")

    # Fetch from environment; use default if provided and env var unset
    env_value = os.getenv(name, None)
    if env_value is not None:
        return env_value

    if default is not None:
        return default

    # If we reach here, variable not set and no default; raise error
    raise KeyError(f"Environment variable '{name}' not set and no default value provided")
