def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import os

    # Ensure commands is a list of strings
    if isinstance(commands, str):
        commands = [commands]
    elif not isinstance(commands, (list, tuple)):
        raise TypeError("commands must be a string or a list/tuple of strings")

    # Ensure args is a list of arguments (string or iterable)
    if isinstance(args, str):
        args = [args]
    elif isinstance(args, (list, tuple)):
        args = list(args)
    else:
        raise TypeError("args must be a string or a list/tuple of strings or argument lists")

    # Prepare the command list
    cmd_list = []
    for i, cmd in enumerate(commands):
        if not isinstance(cmd, str):
            raise TypeError("each command must be a string")
        # Determine args for this command
        if i < len(args):
            cmd_args = args[i]
        else:
            cmd_args = ''
        if isinstance(cmd_args, str):
            full_cmd = [cmd] + [cmd_args]
        elif isinstance(cmd_args, (list, tuple)):
            full_cmd = [cmd] + list(cmd_args)
        else:
            raise TypeError("each element in args must be a string or a list/tuple of strings")
        cmd_list.append(full_cmd)

    # Environment handling
    if env is None:
        use_env = os.environ.copy()
    else:
        if not isinstance(env, dict):
            raise TypeError("env must be a dictionary of environment variables")
        use_env = os.environ.copy()
        use_env.update(env)

    results = []
    for full_cmd in cmd_list:
        if verbose:
            print(f"Executing: {' '.join(full_cmd)}")
        try:
            completed = subprocess.run(
                full_cmd,
                cwd=cwd,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE if not hide_stderr else subprocess.DEVNULL,
                env=use_env,
                text=True,
                check=False,
            )
            results.append(completed)
            if verbose:
                print(f"Return code: {completed.returncode}")
                if completed.stdout:
                    print(f"stdout:\n{completed.stdout}")
                if not hide_stderr and completed.stderr:
                    print(f"stderr:\n{completed.stderr}")
        except FileNotFoundError as e:
            raise RuntimeError(f"Command not found: {full_cmd[0]}") from e
        except Exception as e:
            raise RuntimeError(f"Failed to execute command: {' '.join(full_cmd)}") from e

    # Return single CompletedProcess if only one command was run, else list of them
    if len(results) == 1:
        return results[0]
    return results<|return|>

