def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import shlex

    def _run_single(cmd):
        # Build command list
        cmd_parts = shlex.split(cmd)
        if args:
            if isinstance(args, (list, tuple)):
                cmd_parts.extend(args)
            else:
                cmd_parts.append(str(args))
        if verbose:
            print(f"Running command: {' '.join(cmd_parts)}")
        # Run the command
        try:
            result = subprocess.run(
                cmd_parts,
                cwd=cwd,
                env=env,
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL if hide_stderr else subprocess.PIPE,
                check=False,
                text=True
            )
        except FileNotFoundError as e:
            raise RuntimeError(f"Command not found: {cmd_parts[0]}") from e
        # Handle exit status
        if result.returncode != 0:
            err_msg = f"Command {' '.join(cmd_parts)} failed with exit code {result.returncode}"
            if not hide_stderr and result.stderr:
                err_msg += f"\nStderr: {result.stderr.strip()}"
            raise RuntimeError(err_msg)
        # Capture hidden stderr if not suppressed (not used normally)
        if not hide_stderr and result.stderr and verbose:
            print(f"Stderr: {result.stderr.strip()}", file=sys.stderr)
        return result.stdout

    # Determine if multiple commands are to be executed
    if isinstance(commands, (list, tuple)):
        outputs = [_run_single(cmd) for cmd in commands]
        # Return list if more than one output, else single output
        return outputs if len(outputs) > 1 else outputs[0]
    else:
        # Single command
        return _run_single(str(commands))<|return|>

