    """
    mu, sigma = 0.2, 0.1
    try:
        x_arr = np.asarray(x)
    except Exception as exc:
        raise TypeError("Input `x` must be a numeric type or array-like.") from exc

    coeff = 1.0 / (sigma * np.sqrt(2 * np.pi))
    exponent = -((x_arr - mu) ** 2) / (2 * sigma ** 2)
