def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import logging
    from configparser import ConfigParser

    logger = logging.getLogger('config_loader')
    configs = {}
    error_records = []

    def make_error_record(exc, message):
        """Create a LogRecord for an exception."""
        record = logger.makeRecord(
            name=logger.name,
            level=logging.ERROR,
            fn=__file__,
            lno=0,
            msg=message,
            args=(),
            exc_info=(type(exc), exc, exc.__traceback__),
        )
        return record

    def resolve_env_vars(obj):
        """Recursively resolve environment variables in string values."""
        if isinstance(obj, str):
            return os.path.expandvars(obj)
        if isinstance(obj, dict):
            return {k: resolve_env_vars(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [resolve_env_vars(v) for v in obj]
        return obj

    # Ensure we have a sequence
    if isinstance(config_filenames, (str, bytes)):
        filenames = [config_filenames]
    else:
        filenames = list(config_filenames)

    # Import yaml if available
    try:
        import yaml
    except ImportError:
        yaml = None

    for fname in filenames:
        try:
            if not os.path.isfile(fname):
                raise FileNotFoundError(f"Configuration file '{fname}' does not exist.")

            _, ext = os.path.splitext(fname.lower())
            parsed = None

            with open(fname, 'r', encoding='utf-8') as f:
                content = f.read()

            if ext == '.json':
                parsed = json.loads(content)
            elif ext in {'.yaml', '.yml'}:
                if yaml is None:
                    raise ImportError("yaml package is required for .yaml files.")
                parsed = yaml.safe_load(content) or {}
            elif ext == '.ini':
                parser = ConfigParser()
                parser.read_file(f)
                parsed = {s: dict(parser.items(s)) for s in parser.sections()}
            else:
                # Fallback: try JSON first, then YAML, then INI
                try:
                    parsed = json.loads(content)
                except Exception:
                    if yaml:
                        try:
                            parsed = yaml.safe_load(content) or {}
                        except Exception:
                            pass
                if parsed is None:
                    # Try to parse as simple key=value
                    sections = {}
                    current_section = None
                    for line in content.splitlines():
                        line = line.strip()
                        if not line or line.startswith('#'):
                            continue
                        if '=' in line:
                            key, val = line.split('=', 1)
                            key, val = key.strip(), val.strip()
                            if current_section:
                                sections.setdefault(current_section, {})[key] = val
                            else:
                                sections[key] = val
                        else:
                            current_section = line.strip()
                            sections.setdefault(current_section, {})
                    parsed = sections

            if parsed is None:
                raise ValueError(f"Unsupported configuration format for file: {fname}")

            if resolve_env:
                parsed = resolve_env_vars(parsed)

            if overrides:
                for k, v in overrides.items():
                    parsed[k] = v

            configs[fname] = parsed

        except Exception as exc:
            message = f"Failed to load configuration file '{fname}': {exc}"
            record = make_error_record(exc, message)
            error_records.append(record)
            # Log the error (optional)
            logger.error(message, exc_info=exc)

    return configs, error_records<|return|>

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    configs = {}
    log_records = []

    logger = logging.getLogger(__name__)
    overrides = overrides or {}

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                raw = f.read()
        except Exception as exc:
            record = logger.makeRecord(
                logger.name,
                logging.ERROR,
                filename,
                0,
                f"Failed to read file '{filename}': {exc}",
                None,
                None
            )
            log_records.append(record)
            continue

        try:
            if filename.endswith(('.yml', '.yaml')):
                import yaml
                config = yaml.safe_load(raw) or {}
            elif filename.endswith('.json'):
                import json
                config = json.loads(raw)
            elif filename.endswith('.toml'):
                import toml
                config = toml.loads(raw)
            else:
                # default to JSON
                import json
                config = json.loads(raw)
            if not isinstance(config, dict):
                raise ValueError("Parsed configuration is not a dictionary")
        except Exception as exc:
            record = logger.makeRecord(
                logger.name,
                logging.ERROR,
                filename,
                0,
                f"Failed to parse file '{filename}': {exc}",
                None,
                None
            )
            log_records.append(record)
            continue

        # Apply overrides if any
        override_data = overrides.get(filename)
        if override_data is not None:
            if not isinstance(override_data, dict):
                record = logger.makeRecord(
                    logger.name,
                    logging.ERROR,
                    filename,
                    0,
                    f"Override for file '{filename}' is not a dict",
                    None,
                    None
                )
                log_records.append(record)
            else:
                config.update(override_data)

        # Resolve environment variables if requested
        if resolve_env:
            import os
            import re

            env_pattern = re.compile(r'\$\{([^}]+)\}')

            def _resolve(value):
                if isinstance(value, str):
                    return env_pattern.sub(lambda m: os.getenv(m.group(1), ''), value)
                if isinstance(value, dict):
                    return {k: _resolve(v) for k, v in value.items()}
                if isinstance(value, list):
                    return [_resolve(v) for v in value]
                return value

            config = _resolve(config)

        configs[filename] = config

    return configs, log_records<|return|>

