    '''
    import os
    import json
    import logging
    try:
        import yaml
    except Exception:
        yaml = None

    results = {}
    errors = []

    # Ensure we have an iterable of filenames
    if isinstance(config_filenames, str):
        filenames = [config_filenames]
    else:
        filenames = list(config_filenames)

    for fname in filenames:
        try:
            # Expand environment variables if requested
            if resolve_env:
                fname = os.path.expandvars(fname)

            with open(fname, 'r', encoding='utf-8') as f:
                data = f.read()

            # Determine file type based on extension
            ext = os.path.splitext(fname)[1].lower()

            parsed = None
            if ext in {'.json'}:
                parsed = json.loads(data)
            elif ext in {'.yaml', '.yml'} and yaml is not None:
                parsed = yaml.safe_load(data)
            else:
                # Fall back to JSON, warn if yaml expected but unavailable
                try:
                    parsed = json.loads(data)
                except json.JSONDecodeError:
                    # If yaml might be intended but not available
                    if yaml is None and ext in {'.yaml', '.yml'}:
                        raise ValueError(f"YAML file '{fname}' found but 'yaml' module is not installed.")
                    else:
                        raise

            if parsed is None:
                raise ValueError(f"Could not parse file '{fname}'.")
            # Merge overrides if provided
            if overrides and isinstance(overrides, dict):
                # If overrides contains key for this filename, merge
                override_cfg = overrides.get(fname)
                if override_cfg and isinstance(override_cfg, dict):
                    if isinstance(parsed, dict):
                        parsed.update(override_cfg)
                    else:
                        raise TypeError(f"Cannot merge overrides into non-dict configuration for file '{fname}'.")
                # Additionally, if overrides provided as a function or similar:
                elif callable(overrides):
                    merged = overrides(fname, parsed)
                    if isinstance(merged, dict):
                        parsed = merged

            results[fname] = parsed

        except Exception as exc:
            # Create a LogRecord for the error
            logger_name = 'load_configurations'
            level = logging.ERROR
            pathname = fname if isinstance(fname, str) else ''
            lineno = 0
            msg = f"Error loading configuration file '{fname}': {exc}"
            # Use exc_info to include traceback
            record = logging.LogRecord(logger_name, level, pathname, lineno, msg, None, exc_info=exc)
            errors.append(record)

    return results, errors<|return|>

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return
    the results as a tuple of:
        - dict of configuration filename to corresponding parsed configuration,
        - sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json
    import os
    import re
    logger = logging.getLogger('config_loader')

    # ensure we have a list of filenames
    if config_filenames is None:
        return ({}, [])
    if not hasattr(config_filenames, '__iter__') or isinstance(config_filenames, (str, bytes)):
        config_filenames = [config_filenames]

    configs = {}
    errors = []

    env_pattern = re.compile(r'\$\{([^}]+)\}')

    def replace_env(value):
        # Recursively replace env placeholders in string values
        if isinstance(value, str):
            def repl(match):
                var_name = match.group(1)
                return os.getenv(var_name, match.group(0))
            return env_pattern.sub(repl, value)
        elif isinstance(value, dict):
            return {k: replace_env(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [replace_env(v) for v in value]
        else:
            return value

    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                # attempt json parsing first; if fails try yaml fallback
                try:
                    config = json.load(f)
                except json.JSONDecodeError:
                    # attempt yaml if available
                    try:
                        import yaml
                        f.seek(0)
                        config = yaml.safe_load(f)
                    except Exception as exc:
                        # capture YAML parse errors as well
                        record = logger.makeRecord(
                            name='config_loader',
                            level=logging.ERROR,
                            pathname=__file__,
                            lineno=0,
                            msg=f"Failed to parse file {fname!r} as JSON or YAML: {exc}",
                            args=(),
                            exc_info=None
                        )
                        errors.append(record)
                        continue
            # validate that config is a dict
            if not isinstance(config, dict):
                record = logger.makeRecord(
                    name='config_loader',
                    level=logging.ERROR,
                    pathname=__file__,
                    lineno=0,
                    msg=f"Configuration file {fname!r} does not contain a top-level JSON/YAML object",
                    args=(),
                    exc_info=None
                )
                errors.append(record)
                continue

            # resolve environment variables if requested
            if resolve_env:
                config = replace_env(config)

            # apply overrides if provided
            if overrides and isinstance(overrides, dict):
                # overlay overrides onto the config
                def deep_update(d, u):
                    for k, v in u.items():
                        if isinstance(v, dict) and isinstance(d.get(k), dict):
                            deep_update(d[k], v)
                        else:
                            d[k] = v
                deep_update(config, overrides)

            configs[fname] = config
        except OSError as exc:
            record = logger.makeRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=__file__,
                lineno=0,
                msg=f"Error opening configuration file {fname!r}: {exc}",
                args=(),
                exc_info=None
            )
            errors.append(record)
        except Exception as exc:
            record = logger.makeRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=__file__,
                lineno=0,
                msg=f"Unexpected error processing {fname!r}: {exc}",
                args=(),
                exc_info=None
            )
            errors.append(record)

    return (configs, errors)<|return|>

