@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Retrieve the mapping of available handlers.  The class (or a
        # subclass) is expected to provide a class-level dictionary
        # named `_HANDLERS` that maps (major, minor) tuples to handler
        # classes.  If the attribute is missing we fall back to an empty
        # dictionary, which is safe as it simply indicates that no
        # handlers are available.
        handlers = getattr(cls, "_HANDLERS", {})
        if not isinstance(handlers, dict):
            # Defensive fallback – treat non-dict values as an empty set.
            handlers = {}

        # Normalise the return value to a plain dict to avoid leaking
        # the internal mapping which could be mutated by callers.
        def _copy_handlers():
            return dict(handlers)

        # If no specific protocol requested, return all handlers.
        if protocol_version is None:
            return _copy_handlers()

        # Ensure an explicit protocol version is supplied as a tuple.
        if not isinstance(protocol_version, tuple):
            raise TypeError(
                "protocol_version must be a tuple (e.g. (3, 5)) or None"
            )

        # Return the matching handler if it exists, otherwise an empty dict.
        if protocol_version in handlers:
            return {protocol_version: handlers[protocol_version]}
        else:
            return {}<|return|>

