    if other is None:
        return getattr(self, 'scale', None)

    # 2. Validate new scale
    if not isinstance(other, (int, float)):
        raise TypeError("Scale must be a numeric value")
    current_scale = getattr(self, 'scale', None)
    if current_scale is None or current_scale == 0:
        raise LenaValueError("Cannot rescale a graph with unknown or zero current scale")

    # 3. Determine rescale factor
    factor = other / float(current_scale)

    # 4. Rescale last coordinate
    # Attempt to find a list/tuple of point coordinates or individual attributes
    try:
        # Common case: self.data is a list/tuple of coordinate lists
        if hasattr(self, 'data') and isinstance(self.data, (list, tuple)):
            if not self.data:
                raise LenaValueError("Graph has no coordinate data to rescale")
            last_coord = self.data[-1]
            if isinstance(last_coord, (list, tuple)):
                self.data[-1] = [v * factor for v in last_coord]
            else:
                self.data[-1] = last_coord * factor
