            coords = getattr(self, 'coordinates')
            if isinstance(coords, (list, tuple)):
                last = coords[-1]
                if isinstance(last, (list, tuple)):
                    coords[-1] = [v * factor for v in last]
                else:
                    coords[-1] = last * factor
        else:
            # No recognizable structure; cannot rescale safely
            raise LenaValueError("Graph coordinate data not in a supported format for rescaling")
    except Exception as exc:
        raise LenaValueError(f"Error while rescaling coordinates: {exc}") from exc

