    if replacer is None:
        for m in tag_pattern.finditer(text):
            if not is_inside(m.start()):
                tags.add(m.group(1))
        return tags, text

    # Replacer provided: perform replacement only outside code blocks
    def repl_func(m: re.Match) -> str:
        start = m.start()
        if is_inside(start):
            return m.group(0)  # keep original inside code
        tag = m.group(1)
        tags.add(tag)
        try:
            return replacer(tag)
        except Exception as exc:
            # If replacer fails, fall back to original tag
            return m.group(0)

    replaced_text = tag_pattern.sub(repl_func, text)
    return tags, replaced_text<|return|>

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re

    if not isinstance(text, str):
        raise TypeError("text must be a string")

    # Pattern to match markdown links [text](url)
    md_link_pattern = re.compile(r'\[([^\]]+)]\((http[s]?://[^\s)]+)\)')

    # Pattern to match plain URLs starting with http://, https:// or www.
    url_pattern = re.compile(r'(https?://[^\s]+|www\.[^\s]+)')

    # Function to generate anchor tag with attributes
    def _make_anchor(href, display_text=None):
        # Ensure href starts with http/https
        if not href.startswith(('http://', 'https://')):
            href_full = 'http://' + href.lstrip('www.')
        else:
            href_full = href
        attrs = ' target="_blank" rel="noopener noreferrer"'
        return f'<a href="{href_full}"{attrs}>{display_text or href}</a>'

    # Convert markdown links first
    def md_replacer(match):
        txt, link = match.group(1), match.group(2)
        return _make_anchor(link, txt)

    text = md_link_pattern.sub(md_replacer, text)

    # Convert plain URLs
    def url_replacer(match):
        url = match.group(1)
        return _make_anchor(url)

    text = url_pattern.sub(url_replacer, text)

    return text<|return|>

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not isinstance(text, str):
        return text
    if not text:
        return text
    import re
    url_pattern = re.compile(r'\b((https?://|www\.)[^\s<>"\'`]+)')
    def replace(match):
        url = match.group(1)
        href = url if url.startswith(('http://', 'https://')) else 'http://' + url
        return f'<a href="{href}" rel="nofollow" target="_blank" class="text-link">{url}</a>'
    parts = re.split(r'(<a\b[^>]*>.*?</a>)', text, flags=re.IGNORECASE|re.DOTALL)
    new_parts = []
    for i, part in enumerate(parts):
        if i % 2 == 0:
            new_parts.append(url_pattern.sub(replace, part))
        else:
            new_parts.append(part)
    return ''.join(new_parts)<|return|>

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    if not isinstance(url, str) or not url:
        raise TypeError("url must be a non-empty string")

    # Use urllib to perform a HEAD request (Python 3.3+)
    try:
        import urllib.request
        import urllib.error
    except Exception:  # pragma: no cover
        return None

    # Build a HEAD request
    try:
        req = urllib.request.Request(url, method="HEAD")
    except TypeError:
        # 'method' keyword available in urllib 3.3+. For older versions, use data=None
        try:
            req = urllib.request.Request(url, data=b'')
        except Exception:  # pragma: no cover
            return None

    try:
        with urllib.request.urlopen(req, timeout=10) as response:
            # response.getheader is case-insensitive
            content_type = response.getheader("Content-Type")
            return content_type  # May be None if header absent
    except (urllib.error.HTTPError, urllib.error.URLError):
        # Network or HTTP error; gracefully return None
        return None
    except Exception:
        # Any other unexpected error
        return None<|return|>

