def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        import hashlib, base64
        # Determine the bytes representation of the document
        if isinstance(doc, (bytes, bytearray)):
            data = bytes(doc)
        elif isinstance(doc, str):
            data = doc.encode("utf-8")
        else:
            # Assume an lxml element or similar XML node
            try:
                from lxml import etree
                data = etree.tostring(doc, method="c14n")
            except Exception:
                # fallback: try converting to string
                data = str(doc).encode("utf-8")

        # Compute SHA-256 hash of the canonicalised document
        digest = hashlib.sha256(data).digest()

        # Decode the provided base64 signature
        try:
            signature_bytes = base64.b64decode(signature)
        except Exception:
            return False

        # Compare computed digest with the signature
        return digest == signature_bytes
    except Exception:
        # Any unexpected error results in verification failure
        return False<|return|>

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Import required modules.  These are only imported when the function
    # is called so that callers that never use the function are not
    # forced to have the optional dependencies installed.
    try:
        from lxml import etree
        import xmlsec
    except Exception as exc:
        raise ImportError(
            "The verify_relayable_signature function requires the "
            "lxml and python-xmlsec packages.  Error: %s" % exc
        )

    # ------------------------------------------------------------------
    # 1. Parse the XML document if needed
    # ------------------------------------------------------------------
    if isinstance(doc, (bytes, str)):
        try:
            root = etree.fromstring(doc)
        except Exception as exc:
            raise ValueError("Provided xml document could not be parsed: %s" % exc)
    elif isinstance(doc, etree._Element):
        root = doc
    else:
        raise TypeError(
            "doc must be a bytes, str, or lxml.etree.Element instance"
        )

    # ------------------------------------------------------------------
    # 2. Handle the signature input
    # ------------------------------------------------------------------
    # The signature argument is accepted for backwards compatibility.
    # If it is provided, it must be a base64 encoded signature string
    # or raw bytes.  If omitted, the function will look for a
    # ``<ds:Signature>`` element inside the XML document.
    sig_bytes = None
    if signature is not None:
        if isinstance(signature, (bytes, bytearray)):
            sig_bytes = signature
        elif isinstance(signature, str):
            import base64
            try:
                sig_bytes = base64.b64decode(signature)
            except Exception as exc:
                raise ValueError(
                    "signature string is not valid base64: %s" % exc
                )
        else:
            raise TypeError(
                "signature must be bytes, bytearray or base64 encoded string"
            )

    # ------------------------------------------------------------------
    # 3. Locate the Signature node in the XML tree
    # ------------------------------------------------------------------
    # If the caller supplied a raw signature, we create a dummy <Signature>
    # element containing it; otherwise we look for an existing node.
    if sig_bytes is not None:
        # Build a minimal Signature node containing the raw signature
        dummy_root = etree.Element("dummy")
        dummy_sig = etree.SubElement(dummy_root, xmlsec.Node.SIGNATURE)
        dummy_sig.text = None
        # xmlsec expects the signature element inside the document; we
        # also need to attach it to a proper parent (the root).
        # Create a temporary XML that wraps the raw signature bytes.
        signature_xml = b"<Signature xmlns='http://www.w3.org/2000/09/xmldsig#'>%s</Signature>" % sig_bytes
        try:
            dummy_sig = etree.fromstring(signature_xml)
        except Exception as exc:
            raise ValueError(
                "Provided signature could not be parsed as XML: %s" % exc
            )
        sign_node = dummy_sig
    else:
        # Search for an existing Signature element
        sign_node = xmlsec.tree.find_node(root, xmlsec.Node.SIGNATURE)
        if sign_node is None:
            raise ValueError(
                "No <Signature> element found in the XML document "
                "and no explicit signature was provided."
            )

    # ------------------------------------------------------------------
    # 4. Prepare the xmlsec context and key
    # ------------------------------------------------------------------
    ctx = xmlsec.SignatureContext()

    if isinstance(public_key, xmlsec.Key):
        key = public_key
    else:
        # Support key being either a file path or PEM string
        try:
            from pathlib import Path
            # If public_key looks like a file path
            if isinstance(public_key, (str, Path)) and Path(public_key).is_file():
                key = xmlsec.Key.from_file(public_key, xmlsec.KeyFormat.PEM)

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree as ET

    def _strip_ns(tag: str) -> str:
        return tag.split('}', 1)[-1] if '}' in tag else tag

    result = {}
    document = document.strip() if isinstance(document, str) else ''
    if not document:
        raise ValueError("Empty document")

    # Try JSON first
    if document[0] == '{' or document[0] == '[':
        try:
            data = json.loads(document)
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON webfinger document: {e}")
        # Accept both dict or list (list should contain dict)
        if isinstance(data, list):
            if not data:
                raise ValueError("Empty JSON array in webfinger document")
            data = data[0]
        if not isinstance(data, dict):
            raise ValueError("Expected JSON object in webfinger document")
        result['subject'] = data.get('subject')
        result['aliases'] = data.get('aliases', [])
        result['links'] = data.get('links', [])
        return result

    # Otherwise treat as XML (XRD)
    try:
        root = ET.fromstring(document)
    except ET.ParseError as e:
        raise ValueError(f"Invalid XML webfinger document: {e}")

    # Extract subject
    subject_elem = root.find('.//*')
    if subject_elem is not None:
        for child in root:
            if _strip_ns(child.tag).lower() == 'subject':
                result['subject'] = child.text
                break

    # Extract aliases
    aliases = []
    for child in root:
        if _strip_ns(child.tag).lower() == 'alias':
            if child.text:
                aliases.append(child.text)
    if aliases:
        result['aliases'] = aliases

    # Extract links
    links = []
    for child in root:
        if _strip_ns(child.tag).lower() == 'link':
            link_dict = {}
            # attributes
            for attr in child.attrib:
                link_dict[attr] = child.attrib[attr]
            # nested tags
            for sub in child:
                name = _strip_ns(sub.tag).lower()
                if sub.text:
                    link_dict[name] = sub.text
            links.append(link_dict)
    if links:
        result['links'] = links

    if not result:
        raise ValueError("Could not parse webfinger document")
    return result<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str):
        raise TypeError("document must be a string")

    doc_str = document.strip()
    if not doc_str:
        raise ValueError("document is empty or contains only whitespace")

    # Try to parse as JSON first
    try:
        data = json.loads(doc_str)
        if not isinstance(data, dict):
            raise ValueError("JSON webfinger must be an object")
        # Ensure required components are present; if missing, treat as error
        if "subject" not in data or "links" not in data:
            raise ValueError("JSON webfinger missing required keys")
        # Normalise links: ensure each link is a dict
        links = data.get("links")
        if not isinstance(links, list):
            raise ValueError("JSON webfinger 'links' must be a list")
        # Convert each link to a plain dict if it's an object
        normalized_links = []
        for link in links:
            if isinstance(link, dict):
                normalized_links.append(link)
            else:
                raise ValueError("Each link in JSON must be an object")
        data["links"] = normalized_links
        # Handle optional aliases
        aliases = data.get("aliases")
        if aliases is not None and not isinstance(aliases, list):
            raise ValueError("JSON webfinger 'aliases' must be a list if present")
        return data
    except json.JSONDecodeError:
        # Not JSON, fall back to XML (XRD)
        pass

    # Attempt to parse as XRD XML
    try:
        root = ET.fromstring(doc_str)
    except ET.ParseError as e:
        raise ValueError(f"Document not parseable as JSON or XRD XML: {e}") from e

    # Extract subject
    subject_elem = root.find("subject")
    subject = subject_elem.text.strip() if subject_elem is not None and subject_elem.text else None
    if subject is None:
        raise ValueError("Missing 'subject' element in XRD")

    # Extract aliases (old format may use 'alias' tags)
    alias_elements = root.findall("alias")
    if not alias_elements:
        alias_elements = root.findall("aliases")
    aliases = [a.text.strip() for a in alias_elements if a.text]
    if not aliases:
        aliases = None

    # Extract links
    link_elements = root.findall("link")
    links: List[Dict] = []
    for link_elem in link_elements:
        # Convert attributes to a dict; include nested elements if needed
        link_info = {k: v.strip() for k, v in link_elem.attrib.items()}
        # Handle child elements like 'rel', 'type', 'template' etc.
        for child in list(link_elem):
            child_text = child.text.strip() if child.text else ""
            link_info[child.tag] = child_text
        links.append(link_info)

    result: Dict = {"subject": subject}
    if aliases:
        result["aliases"] = aliases
    result["links"] = links
    return result
