def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # First try JSON format
    try:
        data = json.loads(document)
        if isinstance(data, dict) and "subject" in data:
            subject = data.get("subject")
            links_raw = data.get("links", [])
            links = []
            for link in links_raw:
                if isinstance(link, dict):
                    links.append({
                        "rel": link.get("rel"),
                        "type": link.get("type"),
                        "href": link.get("href")
                    })
            return {"subject": subject, "links": links}
    except Exception:
        pass  # fall back to XRD parsing

    # Try XRD (XML) format
    try:
        root = ET.fromstring(document)

        def _strip_ns(tag: str) -> str:
            """Remove XML namespace from tag."""
            return tag[tag.find("}") + 1 :] if "}" in tag else tag

        # Find <Subject>
        subject_elem = root.find(
            "./" + _strip_ns("Subject"), namespaces=root.nsmap if hasattr(root, "nsmap") else {}
        )
        subject = subject_elem.text if subject_elem is not None else None

        # Find all <Link> elements
        links = []
        for link_elem in root.findall(
            "./" + _strip_ns("Link"), namespaces=root.nsmap if hasattr(root, "nsmap") else {}
        ):
            links.append(
                {
                    "rel": link_elem.get("rel"),
                    "type": link_elem.get("type"),
                    "href": link_elem.get("href"),
                }
            )
        return {"subject": subject, "links": links}
    except (ET.ParseError, SyntaxError):
        pass

    # If we reach here, the document was neither valid JSON nor valid XRD
    raise ValueError(
        "Invalid Diaspora webfinger document: expected JSON or XRD format."
    )
