def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    doc = document.strip()
    if not doc:
        return {}

    # JSON webfinger
    if doc[0] in ('{', '['):
        try:
            data = json.loads(doc)
            if not isinstance(data, dict):
                raise ValueError("JSON Webfinger must be a dictionary.")
            return data
        except Exception as e:
            raise ValueError(f"Invalid JSON Webfinger: {e}") from e

    # XRD webfinger
    try:
        root = ET.fromstring(doc)
    except ET.ParseError as e:
        raise ValueError(f"Invalid XML Webfinger: {e}") from e

    result: Dict = {}

    # Subject
    subject_el = root.find('Subject')
    if subject_el is None:
        # Try namespace
        subject_el = root.find('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Subject')
    if subject_el is not None:
        result['subject'] = subject_el.text or ''

    # Links
    links = []
    for link in root.findall('Link') + root.findall('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link'):
        links.append(link.attrib)
    if links:
        result['links'] = links

    # Canonical
    canonical_el = root.find('Canonical')
    if canonical_el is None:
        canonical_el = root.find('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Canonical')
    if canonical_el is not None:
        result['canonical'] = canonical_el.text or ''

    return result<|return|>

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    try:
