        from urllib.error import URLError, HTTPError
    except Exception:
        return None

    if not isinstance(handle, str):
        return None
    parts = handle.split('@', 1)
    if len(parts) != 2:
        return None
    host = parts[1]
    resource = f'acct:{handle}'
    url = f'https://{host}/.well-known/webfinger?resource={resource}'
    headers = {
        'Accept': 'application/jrd+json, application/json, text/plain'
    }
    req = Request(url, headers=headers)
    try:
        with urlopen(req, timeout=10) as resp:
            if resp.getcode() != 200:
                return None
            content = resp.read()
            try:
                return content.decode('utf-8', errors='replace')
            except Exception:
                return None
    except (HTTPError, URLError, ValueError):
        return None
    except Exception:
        return None
