    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    # Basic validation
    if not isinstance(handle, str) or not handle:
        return {}

    try:
        # Dynamically import required modules
        urllib_request = __import__('urllib.request')
        urllib_parse = __import__('urllib.parse')
        json = __import__('json')
    except Exception:
        # If imports fail, return empty dict
        return {}

    # Normalize the handle
    # Ensure it starts with 'acct:'
    resource = handle.strip()
    if not resource.lower().startswith('acct:'):
