def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    # Basic validation
    if not url:
        raise ValueError("URL must not be empty")

    if not isinstance(timeout, (int, float)):
        raise TypeError("timeout must be a number")

    if not isinstance(method, str):
        raise TypeError("method must be a string")

    # Normalise method
    method = method.lower()

    # Validate method
    allowed_methods = {"get", "post", "put", "delete", "patch", "head", "options"}
    if method not in allowed_methods:
        raise ValueError(f"Unsupported HTTP method: {method!r}")

    try:
        # Forward all additional arguments to requests.request
        resp = requests.request(method, url, data=data, timeout=timeout, *args, **kwargs)
        # Ensure we get an integer status code
        status = getattr(resp, "status_code", None)
        if isinstance(status, int):
            return (status, None)
        else:
            # If for some reason status is not an int, treat as error
            return (None, RuntimeError("Unexpected response status type"))
    except Exception as exc:  # Broad catch to include requests’ exceptions and any misc errors
        # Return None for status if we cannot reach a response
        return (None, exc)<|return|>

