    # Normalize settings_dirs to a list
    if isinstance(settings_dirs, str):
        settings_dirs = [settings_dirs]
    elif not isinstance(settings_dirs, (list, tuple, set)):
        raise TypeError("settings_dirs must be a string or an iterable of directory paths")

    # Determine search patterns
    if spec_option is None or spec_option == '':
        patterns = ['*']
    elif isinstance(spec_option, (list, tuple, set)):
        patterns = list(spec_option)
        if not all(isinstance(p, str) for p in patterns):
            raise TypeError("All items in spec_option must be strings")
    elif isinstance(spec_option, str):
        patterns = [spec_option]
    else:
        raise TypeError("spec_option must be a string, list/tuple/set of strings, or None")

    file_names = []

    for dir_path in settings_dirs:
        if not isinstance(dir_path, str):
            raise TypeError(f"Directory path must be a string, got {type(dir_path).__name__}")
        if not os.path.isdir(dir_path):
            # Skip non-existent or non-directory paths
            continue

        for root, _, files in os.walk(dir_path):
            for filename in files:
                if any(fnmatch.fnmatch(filename, pat) for pat in patterns):
                    file_names.append(os.path.join(root, filename))

    return sorted(file_names)<|return|>

