    import copy

    if not hasattr(self, "_groups"):
        raise AttributeError("Instance missing '_groups' attribute needed for include resolution.")

    def merge_into(target, inc_names):
        """Merge the dictionaries corresponding to inc_names into target."""
        for name in inc_names:
            if name not in self._groups:
                raise KeyError(f"Include group '{name}' not found in spec files.")
            inc_dict = self._groups[name]
            # Copy the include dictionary to avoid mutating the source
            for k, v in copy.deepcopy(inc_dict).items():
                # Do not overwrite an existing key unless it is a dict/list we can merge
                if k not in target:
                    target[k] = v
                else:
                    # If both values are dicts or lists, merge recursively
                    if isinstance(target[k], dict) and isinstance(v, dict):
                        target[k].update(v)
                    elif isinstance(target[k], list) and isinstance(v, list):
                        target[k].extend(v)
                    # otherwise, keep the original value to avoid accidental overrides

    def recurse(current):
        """Recursively walk the parser dictionary searching for include directives."""
        if isinstance(current, dict):
            if "_include" in current:
                inc_val = current.pop("_include")
                # Normalize to a list of strings
                if isinstance(inc_val, str):
                    inc_list = [inc_val]
                elif isinstance(inc_val, list):
                    inc_list = inc_val
                else:
                    raise ValueError("The '_include' directive must be a string or a list of strings.")
                merge_into(current, inc_list)
            for val in current.values():
                recurse(val)
        elif isinstance(current, list):
            for item in current:
                recurse(item)

    recurse(parser_dict)
    return parser_dict
