def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files."""
        # We expect the spec file to optionally contain a top‑level key `include`
        # which may point to a file path (str) or another include dict.
        # The method builds a single dictionary that merges all the groups
        # found in the included specifications into the current spec.

        # If there is no include directive, simply return the original dict.
        if not parser_dict or not isinstance(parser_dict, dict):
            return parser_dict

        includes = parser_dict.get('include')
        if not includes:
            return parser_dict

        # Helper to safely load an include item
        visited_files = set()  # guard against circular includes

        def _merge(target, source):
            """Recursively merge source into target."""
            if not isinstance(source, dict):
                return
            for k, v in source.items():
                if k == 'include':
                    # Handle nested include directives
                    _process_include(v)
                    continue
                if k not in target:
                    # Direct copy
                    target[k] = v
                else:
                    # Merge lists or dicts
                    if isinstance(target[k], list) and isinstance(v, list):
                        target[k].extend(v)
                    elif isinstance(target[k], dict) and isinstance(v, dict):
                        target[k].update(v)
                    else:
                        # For scalar or mismatched types, overwrite
                        target[k] = v

        def _process_include(item):
            """Process a single include reference."""
            if isinstance(item, str):
                # Treat as a file path; guard against repeats
                if item in visited_files:
                    return
                visited_files.add(item)
                try:
                    with open(item, 'r', encoding='utf-8') as fp:
                        data = json.load(fp)
                    _merge(target_dict, data)
                except Exception:
                    # If the file cannot be read or parsed, skip silently
                    pass
            elif isinstance(item, dict):
                # Direct include of another dict
                _merge(target_dict, item)
            elif isinstance(item, list):
                for sub in item:
                    _process_include(sub)
            else:
                # Unsupported types are ignored
                pass

        # Start merging into a new dictionary to avoid modifying the caller's dict directly.
        target_dict = {}
        try:
            # First merge the included specs
            _process_include(includes)
            # Then merge the remaining keys of the original spec
            _merge(target_dict, parser_dict)
        except Exception as exc:
            # If any error occurs during merging, raise a runtime error
            raise RuntimeError(f"Failed to resolve include directives: {exc}") from exc

        return target_dict<|return|>

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    includes = parser_dict.get("include")
    if not includes:
        return parser_dict

    # Normalize to a list
    if not isinstance(includes, (list, tuple)):
        includes = [includes]

    for inc in includes:
        if isinstance(inc, dict):
            inc_dict = inc
        elif isinstance(inc, str):
            # Try to load a JSON/YAML file containing group definitions
            try:
                import json, os
                # Resolve relative paths against current working directory
                path = os.path.join(os.getcwd(), inc)
                with open(path, "r", encoding="utf-8") as fh:
                    inc_dict = json.load(fh)
            except Exception as exc:
                raise RuntimeError(f"Failed to load include file '{inc}': {exc}") from exc
        else:
            # Unsupported type, skip
            continue

        # Recursively resolve any includes in the loaded dict
        inc_dict = self._include_groups(inc_dict)

        # Merge the included data into the parent dictionary
        for key, val in inc_dict.items():
            if key == "groups":
                parser_dict.setdefault("groups", []).extend(val)
            else:
                parser_dict[key] = val

    # Remove the processed include key
    parser_dict.pop("include", None)
    return parser_dict<|return|>

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files. """
        if not isinstance(parser_dict, dict):
            raise TypeError('parser_dict must be a dict')
        # Pop the include directive if present
        includes = parser_dict.pop('include', None)
        if not includes:
            return parser_dict
        # Accept a single item or a list/tuple of items
        if not isinstance(includes, (list, tuple)):
            includes = [includes]
        for entry in includes:
            # If the entry is a dict, merge it directly
            if isinstance(entry, dict):
                for k, v in entry.items():
                    if k in parser_dict:
                        # Preserve existing keys; skip or warn
                        continue
                    parser_dict[k] = v
                continue
            # Otherwise treat the entry as a group name
            if not isinstance(entry, str):
                raise ValueError('Include entries must be strings or dicts')
            # Resolve the group to a specification dict
            if not hasattr(self, '_load_group'):
                raise AttributeError('self has no method _load_group')
            group_def = self._load_group(entry)
            if not isinstance(group_def, dict):
                raise ValueError(f'Group definition for {entry} must be a dict')
            for k, v in group_def.items():
                if k in parser_dict:
                    continue
                parser_dict[k] = v
        return parser_dict<|return|>

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    resolved = {}
    # Track visited groups to detect circular includes
    visit_stack = set()

    def _merge_group(name):
        if name in visit_stack:
            raise ValueError(f"Circular include detected for group '{name}'.")
        visit_stack.add(name)

        if name not in parser_dict:
            raise KeyError(f"Included group '{name}' not found in parser dictionary.")
        group = parser_dict[name]
        if not isinstance(group, dict):
            raise ValueError(f"Included group '{name}' is not a dictionary.")

        merged = {}
        for key, value in group.items():
            # If the value itself is an include directive, recurse
            if isinstance(value, dict) and 'include' in value:
                nested = _merge_group(value['include'])
                merged.update(nested)
            else:
                merged[key] = value

        visit_stack.remove(name)
        return merged

    for key, value in list(parser_dict.items()):
        if isinstance(value, dict) and 'include' in value:
            # Replace the include placeholder with the merged group
            included = _merge_group(value['include'])
            resolved.update(included)
        else:
            resolved[key] = value

    return resolved<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    # Attempt to fetch the spec dictionary from the object or its class.
    spec = getattr(self, "spec", None) or getattr(self.__class__, "spec", None)
    if not spec:
        return {}

    resolved = {}
    # The spec is expected to contain an 'args' mapping of argument names to
    # default information. Each entry may be a scalar default, a callable,
    # or a dict with a 'default' key.
    args_spec = spec.get("args", {})
    if not isinstance(args_spec, dict):
        return resolved

    for name, default_info in args_spec.items():
        try:
            # Prefer an explicitly set value on the object.
            current_value = getattr(self, name, None)

            # Only compute a default if no value is already present.
            if current_value is None:
                # Interpret the spec entry as a default.
                if isinstance(default_info, dict):
                    default_value = default_info.get("default", None)
                else:
                    default_value = default_info

                # If the default is callable, call it to get the value.
                if callable(default_value):
                    default_value = default_value()

                # If a default was found, set it on the object.
                if default_value is not None:
                    setattr(self, name, default_value)
                    current_value = default_value

            resolved[name] = current_value
        except Exception as e:
            # Any failure to resolve a particular argument is logged
            # but does not prevent the rest of the defaults from being
            # processed.
            resolved[name] = None
    return resolved<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Retrieve specification information, which may be stored in self.spec
    spec = getattr(self, "spec", None)
    if spec is None:
        return defaults

    # Determine how to iterate over the spec entries
    if isinstance(spec, dict):
        # Flat dictionary of name -> default
        items = spec.items()
    elif hasattr(spec, "__iter__"):
        # Iterable of objects that may have 'name' and 'default' attributes
        items = ((getattr(item, "name", None), getattr(item, "default", None))
                 for item in spec if hasattr(item, "name"))
    else:
        # Unsupported spec format
        return defaults

    for name, default in items:
        if name is None:
            continue
        # Prefer value already stored on the instance
        value = getattr(self, name, None)
        if value is not None:
            defaults[name] = value
        elif default is not None:
            # Fallback to the default defined in the specification
            defaults[name] = default
    return defaults<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    # Try to retrieve the argument specifications from the instance
    try:
        spec_args = self.spec.get('arguments', []) if hasattr(self, 'spec') else []
    except Exception:
        spec_args = []

    # Walk through each specification entry
    for arg in spec_args or []:
        # Determine the key name for the argument
        name = arg.get('id') or arg.get('name')
        if not name:
            continue

        # If a default is explicitly given, use it
        if 'default' in arg:
            defaults[name] = arg['default']
            continue

        # If no explicit default, infer one from the type if available
        type_ = arg.get('type')
        if type_ == 'int':
            defaults[name] = 0
        elif type_ == 'float':
            defaults[name] = 0.0
        elif type_ == 'bool':
            defaults[name] = False
        else:
            defaults[name] = None

    # Store the computed defaults on the instance for further use
    setattr(self, 'defaults', defaults)
    return defaults<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    # Start with an empty dict of defaults
    defaults = {}
    # 1. Try to read defaults from a 'spec' attribute, if present.
    try:
        spec = getattr(self, 'spec', {})
        if isinstance(spec, dict):
            # The spec might contain a 'defaults' key mapping argument names to values
            spec_defaults = spec.get('defaults', {})
            if isinstance(spec_defaults, dict):
                defaults.update(spec_defaults)
    except Exception:
        # Silently ignore any issue reading the spec
        pass

    # 2. Fallback: look for attributes on the instance that follow a 'default_<arg>' convention.
    try:
        for attr_name in dir(self):
            if attr_name.startswith("default_"):
                arg = attr_name.split("default_", 1)[1]
                if arg not in defaults:
                    defaults[arg] = getattr(self, attr_name)
    except Exception:
        # Silently ignore any issues while scanning attributes
        pass

    # 3. Optional: merge with any externally provided defaults (e.g., from a config dict)
    #    If the instance has a 'cfg' attribute that is a dict of defaults, incorporate it.
    try:
        cfg = getattr(self, "cfg", {})
        if isinstance(cfg, dict):
            for k, v in cfg.items():
                if k not in defaults:
                    defaults[k] = v
    except Exception:
        pass

    # Return a copy to prevent accidental external mutation
    return dict(defaults)<|return|>

