def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Basic type checks
    if not isinstance(cli_args, dict):
        raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
    if not isinstance(answer_file_args, dict):
        raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

    # Merge argument dictionaries (cli_args can override answer file arguments)
    merged_args = {}
    merged_args.update(answer_file_args)
    merged_args.update(cli_args)

    # Determine what is considered deprecated; default to empty dict/list
    deprecated_map = getattr(self, "deprecated_args", None)
    if deprecated_map is None:
        deprecated_map = {}
    # If the attribute is a list/set/tuple, convert it to a mapping with None values
    elif not isinstance(deprecated_map, dict):
        if isinstance(deprecated_map, (set, list, tuple)):
            deprecated_map = {k: None for k in deprecated_map}
        else:
            raise TypeError(f"deprecated_args must be a dict or iterable of keys, got {type(deprecated_map).__name__}")

    # Warn for each deprecated key found
    warned = set()
    for key in merged_args:
        if key in deprecated_map and key not in warned:
            replacement = deprecated_map[key]
            if replacement:
                msg = f"Argument '{key}' is deprecated; use '{replacement}' instead."
            else:
                msg = f"Argument '{key}' is deprecated and has no replacement."
            print(msg)
            warned.add(key)"""
