            if hasattr(self, "commands") and isinstance(self.commands, dict):
                cmd_obj = self.commands.get(command_name)
            # If the instance has an attribute listing parser objects
            elif hasattr(self, "command_parsers") and isinstance(self.command_parsers, (list, tuple)):
                for parser in self.command_parsers:
                    if getattr(parser, "name", None) == command_name:
                        cmd_obj = parser
