def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Try to fetch the parser object for the command. The exact attribute name
    # may vary, so we look for a few common options.
    parser = None
    if hasattr(self, 'parsers') and isinstance(self.parsers, dict):
        parser = self.parsers.get(command_name)
    if parser is None and hasattr(self, 'commands') and isinstance(self.commands, dict):
        # some codebases use a `commands` mapping of name -> parser
        parser = self.commands.get(command_name)
    if parser is None:
        raise ValueError(f"Unknown command name: {command_name}")

    # If the parser already offers a direct way to get its option specs,
    # use it.
    if hasattr(parser, 'get_option_specs'):
        try:
            opts = parser.get_option_specs()
            if isinstance(opts, (list, tuple)):
                return list(opts)
        except Exception:
            pass

    # Fallback to introspecting argparse style objects
    options = set()
    # argparse parsers store actions in the _actions attribute
    actions = getattr(parser, "_actions", [])
    for act in actions:
        # Skip positional arguments
        if not hasattr(act, "option_strings"):
            continue
        for opt in act.option_strings:
            if opt:  # non-empty string
                options.add(opt)

    # If nothing was found, return an empty list and emit a warning
    if not options:
        # It's possible that this parser stores options differently.
        # Attempt common alternatives.
        if hasattr(parser, "options"):
            opts = getattr(parser, "options")
            if isinstance(opts, (list, tuple)):
                options.update(opts)
        if not options:
            # Log a lightweight warning if logging available
            if hasattr(self, "log") and hasattr(self.log, "warning"):
                self.log.warning(f"No options discovered for command '{command_name}'")
    return sorted(options)<|return|>

