def _get_conditionally_required_args(self, command_name, options_spec, args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when`` condition
        """
        conditional_args = []

        for opt in options_spec:
            # Skip options that don't specify a name or a required_when condition
            if 'name' not in opt or 'required_when' not in opt:
                continue

            cond = opt['required_when']
            matched = False

            # Helper to evaluate a single condition
            def evaluate_condition(c):
                nonlocal matched
                try:
                    # Callable condition
                    if callable(c):
                        matched = bool(c(args, command_name))
                        return matched
                    # String condition – evaluate in the context of args and command_name
                    if isinstance(c, str):
                        allowed_names = {'args': args, 'command_name': command_name}
                        matched = bool(eval(c, {}, allowed_names))
                        return matched
                    # Dict condition – check that all key/value pairs match the provided args
                    if isinstance(c, dict):
                        matched = all(args.get(k) == v for k, v in c.items())
                        return matched
                    # Iterable of conditions (list/tuple)
                    if isinstance(c, (list, tuple)):
                        for sub in c:
                            if evaluate_condition(sub):
                                return True
                        return False
                    # Fallback to truthiness of the condition itself
                    matched = bool(c)
                    return matched
                except Exception:
                    # If anything goes wrong while evaluating the condition, treat it as non-matching
                    matched = False
                    return False

            # Evaluate the condition (which may itself be a composite)
            if isinstance(cond, (list, tuple)):
                # If the required_when is a list/tuple, treat it as an OR of conditions
                for sub_cond in cond:
                    if evaluate_condition(sub_cond):
                        matched = True
                        break
            else:
                matched = evaluate_condition(cond)

            if matched:
                conditional_args.append(opt['name'])

        return conditional_args<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

