def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """

    def _value(key, src):
        """Helper to extract a value from a dict or object."""
        if isinstance(src, dict):
            return src.get(key)
        return getattr(src, key, None)

    result = []
    for opt in options_spec:
        name = opt.get("name")
        if name is None:
            continue  # skip options without a name

        if "required_when" not in opt:
            continue

        cond = opt["required_when"]
        matched = False

        # Callable condition
        if callable(cond):
            try:
                matched = bool(cond(args))
            except Exception:
                matched = False

        # Dictionary condition (possibly with command filtering)
        elif isinstance(cond, dict):
            # Allow command filtering
            if cond.get("command") not in (None, command_name):
                matched = False
            else:
                # Remove the command key if present
                remaining = {
                    k: v for k, v in cond.items() if k not in ("command",)
                }
                if remaining:
                    matched = all(
                        _value(k, args) == v for k, v in remaining.items()
                    )
                else:
                    matched = True

        # List of dictionary conditions (any matching is enough)
        elif isinstance(cond, list):
            for subcond in cond:
                if not isinstance(subcond, dict):
                    continue
                # Command filtering
                if subcond.get("command") not in (None, command_name):
                    continue
                remaining = {
                    k: v for k, v in subcond.items() if k not in ("command",)
                }
                if all(_value(k, args) == v for k, v in remaining.items()):
                    matched = True
                    break

        if matched:
            result.append(name)

    return result<|return|>

