            # No length limit specified; skip.
            continue

        # Check that the value has a length
        if not isinstance(value, (str, list, tuple, set, dict)):
            # If it's not a collection type, skip length check.
            continue

        if len(value) > max_len:
            raise ValueError(
                f"Argument '{name}' exceeds maximum length of {max_len} (got {len(value)})."
            )

    # If no exception was raised, all checks passed
    return True<|return|>

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments. Expected to be a mapping.
    """
    # Ensure we have a mapping of allowed choices. This implementation assumes that
    # the instance provides a ``choices`` attribute that maps argument names to
    # iterables of allowed values. If no such attribute exists, we simply return.
    if not hasattr(self, 'choices'):
        return

    if not isinstance(args, dict):
        raise TypeError(f"Expected a dict of arguments, got {type(args).__name__}")

    # Iterate over each argument provided.
    for key, val in args.items():
        if key not in self.choices:
            # If there's no restriction for this key, skip it.
            continue

        allowed = self.choices[key]

        # Allow a single value or a collection of values.
        # If the value is a string (but not an allowed collection), treat it as a single value.
        # For other iterables (list, tuple, set, frozenset, etc.), validate each element.
        if isinstance(val, (list, tuple, set, frozenset)):
            values = val
        else:
            values = [val]

        for v in values:
            if v not in allowed:
                raise ValueError(
                    f"Invalid value for argument '{key}': '{v}'. "
                    f"Allowed choices are: {allowed}"
                )

    # If no exception was raised, all arguments are valid.
    return True<|return|>

