def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Allow either a mapping of argument names to values or an iterable of values.
    if isinstance(args, dict):
        items = args.items()
    else:
        # If args is an iterable of values, treat each as an unnamed argument.
        items = [(None, v) for v in args]
    for key, value in items:
        # Try to obtain constraints from attributes named <arg>_min / <arg>_max
        min_val = None
        max_val = None
        if key is not None:
            min_val = getattr(self, f"{key}_min", None)
            max_val = getattr(self, f"{key}_max", None)
        # Fallback to a class-level or instance-level dictionary of constraints
        if hasattr(self, "arg_constraints") and key in getattr(self, "arg_constraints", {}):
            min_val, max_val = self.arg_constraints[key]
        # Perform the actual comparisons only if constraints are defined
        if (min_val is not None) and (value < min_val):
            raise ValueError(f"Argument '{key}' value {value} is less than minimum {min_val}")
        if (max_val is not None) and (value > max_val):
            raise ValueError(f"Argument '{key}' value {value} exceeds maximum {max_val}")<|return|>

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    try:
        count = len(args)
    except Exception as exc:
        raise TypeError('args must be a collection with a length') from exc

    # Resolve minimum and maximum limits if defined on the instance
    min_limit = getattr(self, 'min_args', None)
    max_limit = getattr(self, 'max_args', None)

    if min_limit is not None:
        if count < min_limit:
            raise ValueError(f'Expected at least {min_limit} arguments, got {count}')

    if max_limit is not None:
        if count > max_limit:
            raise ValueError(f'Expected at most {max_limit} arguments, got {count}')

    return True<|return|>

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments. Can be a single value, a list, tuple or
                 a dict mapping argument names to values.
    """
    min_val = getattr(self, "min", None)
    max_val = getattr(self, "max", None)

    def _check_value(val, key=None):
        if val is None:
            return  # Allow None values without bounds checking
        if not isinstance(val, (int, float)):
            raise TypeError(f"Argument {'{0}'.format(key) if key is not None else ''} must be a numeric type, got {type(val).__name__}")
        if min_val is not None and val < min_val:
            raise ValueError(f"Value {val} for argument {key if key is not None else ''} is less than the minimum allowed {min_val}.")
        if max_val is not None and val > max_val:
            raise ValueError(f"Value {val} for argument {key if key is not None else ''} exceeds the maximum allowed {max_val}.")

    # Handle different container types
    if isinstance(args, (list, tuple)):
        for idx, val in enumerate(args):
            _check_value(val, key=f"index {idx}")
    elif isinstance(args, dict):
        for key, val in args.items():
            _check_value(val, key=key)
    else:
        # Assume a single scalar argument
        _check_value(args, key=None)<|return|>

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                 spec_option):
        """Build the complex argument type

        :param subcommand: the command name
        :param type_name: the complex type name
        :param option_name: the option name
        :param spec_option: option's specifications
        :return: the complex type instance
        """
        # Basic validation of parameters
        if not isinstance(subcommand, str):
            raise TypeError("subcommand must be a string")
        if not isinstance(type_name, str):
            raise TypeError("type_name must be a string")
        if not isinstance(option_name, str):
            raise TypeError("option_name must be a string")
        if spec_option is not None and not isinstance(spec_option, dict):
            raise TypeError("spec_option must be a dict or None")

        # Define a lightweight class to encapsulate the argument type logic
        class _ComplexArgumentType:
            def __init__(self, subcmd, name, opt, spec):
                self.subcommand = subcmd
                self.type_name = name
                self.option_name = opt
                self.spec_option = spec or {}

            def __call__(self, value):
                """Process and validate the argument value according to spec_option."""
                # If the spec defines a type conversion, apply it
                if 'type' in self.spec_option:
                    conv = self.spec_option['type']
                    try:
                        value = conv(value)
                    except Exception as exc:
                        raise ValueError(
                            f"Error converting argument '{self.option_name}' "
                            f"for subcommand '{self.subcommand}': {exc}"
                        ) from exc

                # If choices are specified, enforce them
                if 'choices' in self.spec_option:
                    allowed = self.spec_option['choices']
                    if value not in allowed:
                        raise ValueError(
                            f"Argument '{self.option_name}' for subcommand "
                            f"'{self.subcommand}' must be one of {allowed}, "
                            f"got '{value}'."
                        )

                # If a validator callable is provided, use it
                if 'validator' in self.spec_option and callable(
                        self.spec_option['validator']
                ):
                    validator = self.spec_option['validator']
                    if not validator(value):
                        raise ValueError(
                            f"Validation failed for argument '{self.option_name}' "
                            f"with value '{value}'."
                        )

                return value

            def __repr__(self):
                return (
                    f"<_ComplexArgumentType type={self.type_name} "
                    f"option={self.option_name} subcmd={self.subcommand}>"
                )

        # Instantiate and return the complex type
        return _ComplexArgumentType(subcommand, type_name, option_name, spec_option)<|return|>

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    try:
        if not isinstance(subcommand, str) or not subcommand:
            raise ValueError("subcommand must be a non-empty string")
        if not isinstance(type_name, str) or not type_name:
            raise ValueError("type_name must be a non-empty string")
        if not isinstance(option_name, str) or not option_name:
            raise ValueError("option_name must be a string")
        if spec_option is None:
            raise ValueError("spec_option cannot be None")
    except Exception as e:
        raise ValueError(f"Invalid arguments for create_complex_argumet_type: {e}") from None

    complex_type = {
        'subcommand': subcommand,
        'type_name': type_name,
        'option_name': option_name,
        'spec_option': spec_option
    }
    return complex_type<|return|>

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    import inspect

    # Validate inputs
    if not isinstance(subcommand, (object, type)):
        raise TypeError("subcommand must be an object or class")
    if not isinstance(type_name, str):
        raise TypeError("type_name must be a string")
    if not isinstance(option_name, str):
        raise TypeError("option_name must be a string")
    if spec_option is None:
        spec_option = {}
    if not isinstance(spec_option, (dict,)):
        raise TypeError("spec_option must be a dictionary or None")

    # Resolve the class from the given subcommand context
    try:
        type_cls = getattr(subcommand, type_name)
    except AttributeError as exc:
        raise ValueError(f"Could not find class '{type_name}' in subcommand '{subcommand}'.") from exc

    # Inspect the constructor signature to filter supported kwargs
    try:
        sig = inspect.signature(type_cls)
    except (ValueError, TypeError):
        # If signature inspection fails, fall back to ignoring kwargs
        sig = None

    init_kwargs = {}
    if sig:
        for param in sig.parameters.values():
            if param.name in spec_option:
                init_kwargs[param.name] = spec_option[param.name]

    try:
        instance = type_cls(**init_kwargs)
    except TypeError as exc:
        raise TypeError(f"Failed to instantiate '{type_name}' with arguments {init_kwargs}. "
                        f"Original error: {exc}") from exc

    return instance<|return|>

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Determine a set of keys that should be considered control arguments.
    # If the instance defines a CONTROL_ARGS attribute we use it,
    # otherwise we fall back to prefix based detection.
    control_keys = set()
    if hasattr(self, "CONTROL_ARGS"):
        try:
            control_keys.update(self.CONTROL_ARGS)
        except Exception:
            control_keys = set()
    # Prepare containers for the result
    control_args = {}
    nested_args = {}

    # Normalise the input into an iterable of (key, value) pairs.
    if isinstance(args, dict):
        iterable = args.items()
    else:
        try:
            # Expect a sequence of pairs.
            iterable = args
            # Basic sanity check: each element must be a 2‑tuple.
            if not all(isinstance(it, (list, tuple)) and len(it) == 2 for it in iterable):
                raise ValueError
        except Exception:
            raise TypeError(
                f"{self.__class__.__name__}.get_nested_custom_and_control_args "
                "expects a dict or an iterable of two‑element tuples"
            )

    for item in iterable:
        try:
            key, value = item
        except Exception:
            continue  # skip malformed items

        # Treat keys starting with 'control_' or explicitly listed as control keys
        # as control arguments.  Everything else falls into nested arguments.
        if (
            key in control_keys
            or (isinstance(key, str) and key.lower().startswith("control_"))
        ):
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args<|return|>

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Accept a dict or iterable of key/value pairs / 'k=v' strings
    if isinstance(args, dict):
        items = args.items()
    elif isinstance(args, (list, tuple)):
        if all(isinstance(a, tuple) and len(a) == 2 for a in args):
            items = args
        else:
            items = []
            for a in args:
                if isinstance(a, str) and '=' in a:
                    k, v = a.split('=', 1)
                    items.append((k, v))
                elif isinstance(a, dict):
                    items.extend(a.items())
                else:
                    continue
    else:
        raise TypeError("args must be a dict or an iterable of key/value pairs")

    for k, v in items:
        if isinstance(k, str) and k.lower().startswith('control_'):
            control_args[k] = v
        else:
            nested_args[k] = v

    return control_args, nested_args<|return|>

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    if not isinstance(args, (dict, list, tuple)):
        raise TypeError(f"args must be dict or list/tuple, got {type(args).__name__}")
    control_args = {}
    nested_args = {}
    # If args is a dict, iterate over items
    if isinstance(args, dict):
        items = args.items()
    else:
        # Assume it's an iterable of key-value pairs
        items = args
    for pair in items:
        try:
            key, value = pair
        except Exception:
            # Skip invalid entries
            continue
        if not isinstance(key, str):
            # if key not a string skip or raise
            continue
        # Treat keys starting with 'control_' or 'ctrl_' as control arguments
        if key.startswith("control_") or key.startswith("ctrl_") or key.startswith("ir_"):
            control_args[key] = value
        else:
