def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess, json, shlex, os

    # Validate basic inputs
    if not isinstance(playbook_path, str) or not playbook_path:
        raise ValueError("playbook_path must be a non-empty string")

    # Resolve relative path against workspace if provided and exists
    if hasattr(ir_workspace, "path"):
        abs_path = os.path.join(ir_workspace.path, playbook_path)
        if os.path.exists(abs_path):
            playbook_path = abs_path

    cmd = ["ansible-playbook", playbook_path]

    # Handle verbosity
    if verbose is not None:
        try:
            level = int(verbose)
            if level > 0:
                cmd.extend(["-v"] * level)
        except Exception:
            pass  # ignore invalid verbosity values

    # Handle extra variables
    if isinstance(extra_vars, dict) and extra_vars:
        try:
            extra_json = json.dumps(extra_vars, separators=(',', ':'))
            cmd.extend(["--extra-vars", shlex.quote(extra_json)])
        except Exception:
            raise ValueError("Failed to serialize extra_vars dictionary")

    # Handle other ansible arguments
    if isinstance(ansible_args, dict):
        for key, value in ansible_args.items():
            # Normalize key to form '--key'
            flag = key if key.startswith("--") else f"--{key}"
            if isinstance(value, bool):
                if value:
                    cmd.append(flag)
                # if False, omit the flag
                continue
            if isinstance(value, (list, tuple)):
                for v in value:
                    cmd.extend([flag, str(v)])
                continue
            cmd.extend([flag, str(value)])

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
