    if verbose:
        # Accept int or string
        if isinstance(verbose, int):
            if verbose < 0:
                raise ValueError("verbose must be non-negative")
            cmd.append('-' + 'v' * verbose)
        elif isinstance(verbose, str):
            # Normalize: e.g., 'v', 'vv', 'vvv'
            if all(c == 'v' or c in ('+', '-') for c in verbose):
                cmd.append(f"-{verbose}")
            else:
                raise ValueError(f"Invalid verbose string: {verbose}")
        else:
            raise TypeError("verbose must be int or str")

