    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dict")
        try:
            vars_json = json.dumps(extra_vars, separators=(',', ':'))
        except (TypeError, ValueError) as exc:
            raise ValueError(f"Failed to serialize extra_vars: {exc}") from exc
        cmd.extend(['--extra-vars', vars_json])

    # Additional ansible arguments
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for key, value in ansible_args.items():
            if key.startswith('-'):
                flag = key
            else:
                flag = f"--{key}"
            # If value is None or False, skip
            if value is None or value is False:
                continue
            if value is True:
                cmd.append(flag)
            else:
                # If value is a sequence but not string, expand
                if isinstance(value, (list, tuple)):
                    for v in value:
                        cmd.extend([flag, str(v)])
                else:
                    cmd.extend([flag, str(value)])

    # Ensure the command is run in the workspace directory
    cwd = None
    try:
        cwd = ir_workspace.path
    except AttributeError:
        # If no path attribute, don't set cwd
        cwd = None

    # Run the command
    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            capture_output=True,
            text=True,
            check=True,
        )
    except subprocess.CalledProcessError as exc:
        # Include stdout/stderr in the exception message
        raise RuntimeError(
            f"ansible-playbook failed with code {exc.returncode}\n"
            f"stdout:\n{exc.stdout}\n"
            f"stderr:\n{exc.stderr}"
        ) from exc
    except FileNotFoundError as exc:
        raise RuntimeError("ansible-playbook command not found. "
                           "Ensure ansible is installed and in PATH.") from exc

    return {
        'returncode': result.returncode,
        'stdout': result.stdout,
        'stderr': result.stderr,
    }<|return|>

