    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results as a dict containing 'returncode', 'stdout', 'stderr'
    """
    import subprocess
    import json
    import shlex

    # Validate inputs
    if not isinstance(vars_dict, dict):
        raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")
    if not isinstance(cli_args, (list, tuple, str)):
        raise TypeError(f"cli_args must be a list, tuple or string, got {type(cli_args).__name__}")

    # Ensure CLI args is a list
    if isinstance(cli_args, str):
        cli_args = shlex.split(cli_args)

    # Prepare working directory from workspace if available
    cwd = None
    for attr in ("path", "workspace", "root"):
        if hasattr(ir_workspace, attr):
            cwd = getattr(ir_workspace, attr)
            break

    # Build command
    cmd = ["ansible-playbook"] + list(cli_args) + ["--extra-vars", json.dumps(vars_dict)]

    # Optional logging
    if hasattr(ir_plugin, "log"):
        ir_plugin.log(f"Running ansible command: {' '.join(cmd)}")
    elif hasattr(ir_plugin, "info"):
        ir_plugin.info(f"Running ansible command: {' '.join(cmd)}")

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            capture_output=True,
            text=True,
