    with open(spec_path, "r", encoding="utf-8") as f:
        try:
            data = json.load(f)
        except Exception as exc:
            raise ValueError(f"Failed to parse JSON spec file '{spec_path}': {exc}") from exc

    # Helper function to recursively flatten nested dictionaries
    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            elif isinstance(v, (list, tuple)):
                # For lists or tuples of primitives, join by commas
                if all(not isinstance(item, (dict, list, tuple)) for item in v):
                    items[new_key] = ",".join(map(str, v))
                else:
                    # If elements are dict-like, flatten each with an index suffix
                    for idx, elem in enumerate(v):
                        if isinstance(elem, dict):
                            items.update(_flatten(elem, f"{new_key}{sep}{idx}", sep=sep))
                        else:
                            items[f"{new_key}{sep}{idx}"] = elem
            else:
                items[new_key] = v
        return items

    flat_dict = _flatten(data)
    return flat_dict<|return|>

